class UnstringifiableKey:
    def __str__(self):
        raise RuntimeError("cannot stringify key")


class ShutdownTrackingSocket:
    def __init__(self, error=None):
        self.error = error
        self.shutdown_calls = []

    def shutdown(self, how):
        self.shutdown_calls.append(how)
        if self.error is not None:
            raise self.error


