    def post_with_exhausted_job_ids(self, endpoint, **kwargs):
        existing_output = self.output_dir / TEST_OUTPUT_FILENAME
        existing_output.write_bytes(b"existing-output")
        original_token_hex = app_module.secrets.token_hex
        app_module.secrets.token_hex = lambda byte_count: (
            TEST_JOB_ID if byte_count == app_module.JOB_ID_BYTES else original_token_hex(byte_count)
        )
        try:
            return self.client.post(endpoint, **kwargs)
        finally:
            app_module.secrets.token_hex = original_token_hex

    def post_with_failing_upload_save(self, endpoint, fail_on_call=1, **kwargs):
        original_save = FileStorage.save
        calls = {"count": 0}

        def failing_save(file_storage, destination, *save_args, **save_kwargs):
            calls["count"] += 1
            if calls["count"] == fail_on_call:
                raise OSError("disk full")
            return original_save(file_storage, destination, *save_args, **save_kwargs)

        FileStorage.save = failing_save
        try:
            return self.client.post(endpoint, **kwargs)
        finally:
            FileStorage.save = original_save

    def post_with_failing_thread_start(self, endpoint, **kwargs):
        original_start = app_module.threading.Thread.start

        def failing_start(_thread, *start_args, **start_kwargs):
            raise RuntimeError("can't start new thread")

        app_module.threading.Thread.start = failing_start
        try:
            return self.client.post(endpoint, **kwargs)
        finally:
            app_module.threading.Thread.start = original_start

    def docx_upload(self, filename):
        return BytesIO(self.test_doc_bytes), filename

    @staticmethod
    def rewrite_docx_bytes(docx_bytes, member_name, transform):
        output = BytesIO()
        with (
            zipfile.ZipFile(BytesIO(docx_bytes), "r") as source,
            zipfile.ZipFile(output, "w") as target,
        ):
            for entry in source.infolist():
                payload = source.read(entry.filename)
                if entry.filename == member_name:
                    payload = transform(payload)
                target.writestr(entry, payload)
        return output.getvalue()

    @classmethod
    def build_validator_accepted_malformed_style_docx(cls, docx_bytes):
        def remove_paragraph_style_value(xml_bytes):
            root = format_paper_module.etree.fromstring(xml_bytes)
            paragraph = next(root.iter(format_paper_module.qn("w:p")))
            properties = paragraph.find(format_paper_module.qn("w:pPr"))
            if properties is None:
                properties = format_paper_module.etree.Element(
                    format_paper_module.qn("w:pPr")
                )
                paragraph.insert(0, properties)
            style = properties.find(format_paper_module.qn("w:pStyle"))
            if style is None:
                style = format_paper_module.etree.Element(
                    format_paper_module.qn("w:pStyle")
                )
                properties.insert(0, style)
            style.attrib.clear()
            return format_paper_module.etree.tostring(
                root,
                xml_declaration=True,
                encoding="UTF-8",
                standalone=True,
            )

        return cls.rewrite_docx_bytes(
            docx_bytes,
            "word/document.xml",
            remove_paragraph_style_value,
        )

    @staticmethod
    def build_high_compression_binary_docx(payload_size=1024 * 1024):
        """构造结构合法、仅非 XML 载荷具有极高压缩率的 DOCX。"""
        content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            b'<Default Extension="bin" ContentType="application/octet-stream"/></Types>',
        )
        payload = BytesIO()
        with zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("[Content_Types].xml", content_types)
            archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
            archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
            archive.writestr(
                "word/_rels/document.xml.rels",
                (
                    f'<Relationships xmlns="{app_module.PACKAGE_RELATIONSHIPS_NAMESPACE}">'
                    '<Relationship Id="rIdPayload" '
                    'Type="https://example.test/relationships/payload" '
                    'Target="embeddings/payload.bin"/></Relationships>'
                ).encode(),
            )
            archive.writestr("word/embeddings/payload.bin", b"A" * payload_size)
        return payload.getvalue()

    def assert_duplicate_upload_rejected(self, endpoint, fields, expected_error):
        response = self.client.post(
            endpoint,
            data=MultiDict(fields),
            content_type="multipart/form-data",
        )

        self.assertEqual(response.status_code, 400)
        self.assertEqual(
            response.get_json(),
            {"success": False, "error": expected_error},
        )
        self.assertIsNone(response.headers.get("Connection"))
        self.assertEqual(app_module.PROGRESS_JOBS, {})
        self.assertEqual(list(self.upload_dir.glob("*.docx")), [])
        self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
        self.assertEqual(app_module.ACTIVE_UPLOAD_RESERVATIONS, {})

