    def test_declared_oversized_multipart_closes_before_body_parsing(self):
        with patch.object(
            app_module,
            "get_single_uploaded_file",
            side_effect=AssertionError("oversized request body must not be parsed"),
        ) as multipart_parser:
            response = self.client.post(
                "/api/format",
                data=b"partial multipart body",
                content_type="multipart/form-data; boundary=test",
                environ_overrides={
                    "CONTENT_LENGTH": str(app_module.app.config["MAX_CONTENT_LENGTH"] + 1),
                },
            )

        multipart_parser.assert_not_called()
        self.assertEqual(response.status_code, 413)
        self.assertEqual(response.headers.get("Connection"), "close")

    def test_unread_body_static_responses_do_not_bypass_socket_shutdown(self):
        for path in ("/", "/static/script.js"):
            with self.subTest(path=path):
                server_socket = ShutdownTrackingSocket()
                response = self.client.get(
                    path,
                    data=b"unread request body",
                    content_type="application/octet-stream",
                    environ_overrides={"gunicorn.socket": server_socket},
                )

                self.assertEqual(response.status_code, 200)
                self.assertEqual(response.headers.get("Connection"), "close")
                response.get_data()
                response.close()
                self.assertEqual(
                    server_socket.shutdown_calls,
                    [app_module.socket.SHUT_RDWR],
                )

    def test_display_name_sanitizes_control_chars_and_truncates(self):
        long_name = "论文" * (app_module.MAX_DOWNLOAD_STEM_LENGTH + 20)

        self.assertEqual(
            app_module.get_display_name("../bad\r\nX.docx"),
            "badX",
        )
        self.assertEqual(
            app_module.get_display_name(f"{long_name}.docx"),
            "论文" * (app_module.MAX_DOWNLOAD_STEM_LENGTH // 2),
        )
        self.assertEqual(app_module.get_display_name(None), "document")
        self.assertEqual(app_module.get_display_name(UnstringifiableKey()), "document")

    def test_filename_text_normalization_strips_controls_and_bounds_length(self):
        long_name = "a" * (app_module.MAX_FILENAME_TEXT_LENGTH + 50)
        long_log_name = "b" * (app_module.MAX_LOG_FILENAME_LENGTH + 50)

        self.assertEqual(
            app_module.normalize_filename_text(" ..\\bad\x00\r\nX.docx "),
            "../badX.docx",
        )
        self.assertEqual(
            len(app_module.normalize_filename_text(long_name)),
            app_module.MAX_FILENAME_TEXT_LENGTH,
        )
        self.assertTrue(app_module.allowed_file("paper\x00.DOCX"))
        self.assertFalse(app_module.allowed_file("paper.docx\x00.exe"))
        self.assertEqual(app_module.get_log_filename("..\\bad\x00\r\nX.docx"), "badX.docx")
        self.assertEqual(len(app_module.get_log_filename(long_log_name)), app_module.MAX_LOG_FILENAME_LENGTH)
        self.assertEqual(app_module.get_log_filename(None), "unnamed")

    def test_filename_helpers_reject_malformed_non_string_values(self):
        self.assertTrue(app_module.allowed_file("paper.DOCX"))
        self.assertFalse(app_module.allowed_file(None))
        self.assertFalse(app_module.allowed_file(UnstringifiableKey()))
        self.assertTrue(app_module.is_generated_output(TEST_OUTPUT_FILENAME))
        self.assertFalse(app_module.is_generated_output("deadbeef_output.docx"))
        self.assertFalse(app_module.is_generated_output(f"../{TEST_OUTPUT_FILENAME}"))
        self.assertFalse(app_module.is_generated_output(f"..\\{TEST_OUTPUT_FILENAME}"))
        self.assertFalse(app_module.is_generated_output(UnstringifiableKey()))
        self.assertEqual(
            app_module.get_download_name(UnstringifiableKey(), TEST_OUTPUT_FILENAME),
            TEST_OUTPUT_FILENAME,
        )

    def test_job_ids_use_128_bits_of_random_hex_entropy(self):
        job_ids = {app_module.create_unique_job_id(set()) for _ in range(64)}

        self.assertEqual(app_module.JOB_ID_BYTES, 16)
        self.assertEqual(app_module.JOB_ID_LENGTH, 32)
        self.assertEqual(len(job_ids), 64)
        for job_id in job_ids:
            self.assertRegex(job_id, r"^[0-9a-f]{32}$")
            self.assertTrue(app_module.is_valid_job_id(job_id))
        self.assertFalse(app_module.is_valid_job_id("deadbeef"))
        self.assertFalse(app_module.is_valid_job_id(TEST_JOB_ID.upper()))
        self.assertFalse(app_module.is_valid_job_id(f"g{TEST_JOB_ID[1:]}"))

    def test_json_error_normalizes_malformed_and_long_messages(self):
        long_message = "错误" * (app_module.MAX_JOB_ERROR_MESSAGE_LENGTH + 20)

        with app_module.app.app_context():
            fallback_response, fallback_status = app_module.json_error(UnstringifiableKey(), 400)
            long_response, long_status = app_module.json_error(long_message, 500)
            invalid_status_response, invalid_status = app_module.json_error("坏状态码", 200)
            path_response, path_status = app_module.json_error(
                "处理失败：/tmp/private/api-input.docx\r\n请重试",
                500,
            )

        self.assertEqual(fallback_status, 400)
        self.assertEqual(
            fallback_response.get_json(),
            {"success": False, "error": "请求处理失败，请稍后重试。"},
        )
        self.assertEqual(long_status, 500)
        long_error = long_response.get_json()["error"]
        self.assertLessEqual(len(long_error), app_module.MAX_JOB_ERROR_MESSAGE_LENGTH)
        self.assertTrue(long_error.endswith("…"))
        self.assertEqual(invalid_status, 500)
        self.assertEqual(
            invalid_status_response.get_json(),
            {"success": False, "error": "坏状态码"},
        )
        self.assertEqual(path_status, 500)
        self.assertEqual(
            path_response.get_json(),
            {"success": False, "error": "处理失败：api-input.docx 请重试"},
        )

    def test_job_processing_error_sanitizes_user_visible_paths_and_controls(self):
        error = app_module.JobProcessingError(
            "处理失败：/tmp/private/secret-input.docx\r\n请重试",
            500,
        )
        windows_error = app_module.JobProcessingError(
            "处理失败：C:\\Users\\secret\\paper.docx\t请重试",
            500,
        )

        self.assertEqual(error.message, "处理失败：secret-input.docx 请重试")
        self.assertNotIn("/tmp/private", error.message)
        self.assertEqual(windows_error.message, "处理失败：paper.docx 请重试")
        self.assertNotIn("C:\\Users", windows_error.message)

