    def test_merged_processor_reserves_intermediate_and_final_output_peak(self):
        cover_path = self.upload_dir / f"{TEST_JOB_ID}_cover.docx"
        body_path = self.upload_dir / f"{TEST_JOB_ID}_body.docx"
        cover_path.write_bytes(b"cover")
        body_path.write_bytes(b"body")
        reserved = []

        def capture_reservation(output_path, reserved_bytes=None):
            reserved.append((output_path, reserved_bytes))
            return lambda: None

        def fake_merge(_cover, _body, output_path, **kwargs):
            self.assertEqual(
                kwargs["max_output_bytes"],
                app_module.MAX_OUTPUT_FILE_BYTES,
            )
            Path(output_path).write_bytes(self.test_doc_bytes)
            return {"stats": {}}

        with (
            patch.object(app_module, "reserve_output_storage", side_effect=capture_reservation),
            patch.object(app_module, "merge_cover_and_body", side_effect=fake_merge),
        ):
            result = app_module.process_merged_document(
                cover_path,
                body_path,
                "正文",
                TEST_JOB_ID,
            )

        self.assertTrue(result["success"])
        self.assertEqual(
            reserved,
            [
                (
                    self.output_dir / TEST_OUTPUT_FILENAME,
                    app_module.MAX_OUTPUT_FILE_BYTES * 2,
                )
            ],
        )

    def test_all_processors_map_output_limit_to_413_and_cleanup(self):
        input_path = self.upload_dir / f"{TEST_JOB_ID}_input.docx"
        cover_path = self.upload_dir / f"{TEST_JOB_ID}_cover.docx"
        body_path = self.upload_dir / f"{TEST_JOB_ID}_body.docx"
        first_path = self.upload_dir / f"{TEST_JOB_ID}_first.docx"
        second_path = self.upload_dir / f"{TEST_JOB_ID}_second.docx"
        for path in (input_path, cover_path, body_path, first_path, second_path):
            path.write_bytes(b"input")

        cases = (
            (
                "format_academic_paper",
                lambda: app_module.process_uploaded_document(
                    input_path,
                    "正文",
                    TEST_JOB_ID,
                ),
            ),
            (
                "format_academic_paper_from_text",
                lambda: app_module.process_text_document("正文", TEST_JOB_ID),
            ),
            (
                "merge_cover_and_body",
                lambda: app_module.process_merged_document(
                    cover_path,
                    body_path,
                    "正文",
                    TEST_JOB_ID,
                ),
            ),
            (
                "concatenate_documents",
                lambda: app_module.process_concatenated_document(
                    first_path,
                    second_path,
                    "正文",
                    TEST_JOB_ID,
                ),
            ),
        )

        for formatter_name, run_processor in cases:
            with self.subTest(formatter=formatter_name), patch.object(
                app_module,
                formatter_name,
                side_effect=app_module.OutputSizeLimitExceeded(
                    app_module.MAX_OUTPUT_FILE_BYTES
                ),
            ):
                with self.assertRaises(app_module.JobProcessingError) as caught:
                    run_processor()

                self.assertEqual(caught.exception.status_code, 413)
                self.assertEqual(caught.exception.message, app_module.OUTPUT_TOO_LARGE_MESSAGE)
                self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
                self.assertEqual(app_module.ACTIVE_OUTPUT_RESERVATIONS, {})

