    def test_text_processor_rejects_incomplete_or_corrupt_docx_output(self):
        def build_archive(entries):
            output = BytesIO()
            with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_STORED) as archive:
                for name, payload in entries:
                    archive.writestr(name, payload)
            return output.getvalue()

        missing_document = build_archive(
            [("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)]
        )
        malformed_document = build_archive(
            [
                ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                ("word/document.xml", b"<not-a-word-document/>"),
            ]
        )
        wrong_main_content_type = MINIMAL_CONTENT_TYPES_XML.replace(
            b"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml",
            b"application/xml",
        )
        wrong_content_type_document = build_archive(
            [
                ("[Content_Types].xml", wrong_main_content_type),
                ("word/document.xml", MINIMAL_DOCUMENT_XML),
            ]
        )
        dtd_document_xml = (
            f'<?xml version="1.0"?><!DOCTYPE w:document [<!ENTITY value "expanded">]>'
            f'<w:document xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
            '<w:body><w:p><w:r><w:t>&value;</w:t></w:r></w:p></w:body></w:document>'
        ).encode()
        dtd_document = build_archive(
            [
                ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                ("word/document.xml", dtd_document_xml),
            ]
        )
        dtd_document_utf16 = build_archive(
            [
                ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                ("word/document.xml", dtd_document_xml.decode().encode("utf-16")),
            ]
        )
        missing_body_document = build_archive(
            [
                ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                (
                    "word/document.xml",
                    f'<w:document xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}"/>'.encode(),
                ),
            ]
        )
        deep_document_xml = (
            f'<w:document xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}"><w:body>'.encode()
            + b"<w:custom>" * (app_module.MAX_DOCX_XML_DEPTH + 1)
            + b"</w:custom>" * (app_module.MAX_DOCX_XML_DEPTH + 1)
            + b"</w:body></w:document>"
        )
        deep_document = build_archive(
            [
                ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                ("word/document.xml", deep_document_xml),
            ]
        )
        unsafe_member_name = build_archive(
            [
                ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                ("word/document.xml", MINIMAL_DOCUMENT_XML),
                ("../escape.xml", b"<escape/>"),
            ]
        )
        with self.assertWarns(UserWarning):
            duplicate_document = build_archive(
                [
                    ("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML),
                    ("word/document.xml", MINIMAL_DOCUMENT_XML),
                    ("word/document.xml", MINIMAL_DOCUMENT_XML),
                ]
            )

        binary_content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            b'<Default Extension="bin" ContentType="application/octet-stream"/></Types>',
        )
        crc_corrupt = bytearray(
            build_archive(
                [
                    ("[Content_Types].xml", binary_content_types),
                    ("word/document.xml", MINIMAL_DOCUMENT_XML),
                    ("word/media/blob.bin", b"binary-resource"),
                ]
            )
        )
        with zipfile.ZipFile(BytesIO(crc_corrupt)) as archive:
            media_info = archive.getinfo("word/media/blob.bin")
        header_offset = media_info.header_offset
        filename_length = int.from_bytes(
            crc_corrupt[header_offset + 26 : header_offset + 28],
            "little",
        )
        extra_length = int.from_bytes(
            crc_corrupt[header_offset + 28 : header_offset + 30],
            "little",
        )
        data_offset = header_offset + 30 + filename_length + extra_length
        crc_corrupt[data_offset] ^= 0xFF

        cases = {
            "not-zip": b"not a docx archive",
            "missing-required-member": missing_document,
            "wrong-document-root": malformed_document,
            "wrong-main-content-type": wrong_content_type_document,
            "document-dtd": dtd_document,
            "document-dtd-utf16": dtd_document_utf16,
            "missing-document-body": missing_body_document,
            "excessive-document-depth": deep_document,
            "unsafe-member-name": unsafe_member_name,
            "duplicate-member": duplicate_document,
            "non-xml-crc-corruption": bytes(crc_corrupt),
        }
        for label, output_bytes in cases.items():
            with self.subTest(case=label):
                def invalid_formatter(_text, output_path, **_kwargs):
                    Path(output_path).write_bytes(output_bytes)
                    return {"stats": {}}

                with patch.object(
                    app_module,
                    "format_academic_paper_from_text",
                    side_effect=invalid_formatter,
                ):
                    with self.assertRaises(app_module.JobProcessingError) as caught:
                        app_module.process_text_document("正文", TEST_JOB_ID)

                self.assertEqual(caught.exception.status_code, 500)
                self.assertEqual(
                    caught.exception.message,
                    "排版处理失败，未生成输出文件，请重试。",
                )
                self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
                self.assertEqual(app_module.ACTIVE_OUTPUT_RESERVATIONS, {})

    def test_text_processor_rechecks_output_size_after_integrity_validation(self):
        def formatter(_text, output_path, **_kwargs):
            Path(output_path).write_bytes(self.test_doc_bytes)
            return {"stats": {}}

        def mutating_validator(output_path):
            path = Path(output_path)
            path.write_bytes(path.read_bytes() + b"race")
            return True

        with (
            patch.object(app_module, "format_academic_paper_from_text", side_effect=formatter),
            patch.object(app_module, "is_valid_generated_docx", side_effect=mutating_validator),
        ):
            with self.assertRaises(app_module.JobProcessingError) as caught:
                app_module.process_text_document("正文", TEST_JOB_ID)

        self.assertEqual(caught.exception.status_code, 500)
        self.assertEqual(caught.exception.message, "排版处理失败，未生成输出文件，请重试。")
        self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
        self.assertEqual(app_module.ACTIVE_OUTPUT_RESERVATIONS, {})

    def test_save_uploaded_file_rejects_existing_destination_without_overwriting(self):
        destination = self.upload_dir / f"{TEST_JOB_ID}_input.docx"
        destination.write_bytes(b"existing-upload")
        upload = FileStorage(stream=BytesIO(b"new-upload"), filename="input.docx")

        with self.assertRaises(app_module.JobProcessingError) as caught:
            app_module.save_uploaded_file(upload, destination)

        self.assertEqual(caught.exception.status_code, 503)
        self.assertEqual(caught.exception.message, "服务器临时存储不可用，请稍后重试。")
        self.assertEqual(destination.read_bytes(), b"existing-upload")
        self.assertTrue(upload.stream.closed)

    def test_save_uploaded_file_closes_multipart_stream_after_copy(self):
        destination = self.upload_dir / f"{TEST_JOB_ID}_input.docx"
        upload = FileStorage(stream=BytesIO(b"new-upload"), filename="input.docx")

        size = app_module.save_uploaded_file(upload, destination)

        self.assertEqual(size, len(b"new-upload"))
        self.assertEqual(destination.read_bytes(), b"new-upload")
