    def test_make_json_safe_preserves_normalized_key_collisions(self):
        safe_value = app_module.make_json_safe(
            {
                1: "number",
                "1": "text",
                UnstringifiableKey(): "bad key",
                UnstringifiableKey(): "second bad key",
                "invalid_key": "literal key",
            }
        )

        self.assertEqual(safe_value["1"], "number")
        self.assertEqual(safe_value["1_2"], "text")
        self.assertEqual(safe_value["invalid_key"], "bad key")
        self.assertEqual(safe_value["invalid_key_2"], "second bad key")
        self.assertEqual(safe_value["invalid_key_3"], "literal key")

    def test_normalize_json_key_short_circuits_oversized_keys(self):
        exact_key = "a" * app_module.MAX_JSON_KEY_LENGTH
        long_key = "b" * (app_module.MAX_JSON_KEY_LENGTH + 50)
        sparse_long_key = "c" + (" " * (app_module.MAX_JSON_KEY_LENGTH + 50)) + "d"

        self.assertEqual(app_module.normalize_json_key("  normal key  "), "normal key")
        self.assertEqual(app_module.normalize_json_key(exact_key), exact_key)
        self.assertEqual(len(app_module.normalize_json_key(long_key)), app_module.MAX_JSON_KEY_LENGTH)
        self.assertTrue(app_module.normalize_json_key(long_key).endswith("…"))
        self.assertEqual(app_module.normalize_json_key(sparse_long_key), "c…")

    def test_make_json_safe_caps_oversized_collections(self):
        oversized_map = {
            f"k{i}": i
            for i in range(app_module.MAX_JSON_COLLECTION_ITEMS + 25)
        }
        oversized_list = list(range(app_module.MAX_JSON_COLLECTION_ITEMS + 25))

        safe_value = app_module.make_json_safe(
            {
                "map": oversized_map,
                "list": oversized_list,
            }
        )

        self.assertEqual(len(safe_value["map"]), app_module.MAX_JSON_COLLECTION_ITEMS)
        self.assertEqual(len(safe_value["list"]), app_module.MAX_JSON_COLLECTION_ITEMS)
        self.assertIn("k0", safe_value["map"])
        self.assertIn(f"k{app_module.MAX_JSON_COLLECTION_ITEMS - 1}", safe_value["map"])
        self.assertNotIn(f"k{app_module.MAX_JSON_COLLECTION_ITEMS}", safe_value["map"])
        self.assertEqual(safe_value["list"][-1], app_module.MAX_JSON_COLLECTION_ITEMS - 1)

    def test_make_json_safe_caps_oversized_strings_without_trimming_normal_text(self):
        long_text = "x" * (app_module.MAX_JSON_STRING_LENGTH + 25)

        safe_value = app_module.make_json_safe(
            {
                "normal": "  keep surrounding space  ",
                "long": long_text,
                "nested": [long_text],
            }
        )

        self.assertEqual(safe_value["normal"], "  keep surrounding space  ")
        self.assertLessEqual(len(safe_value["long"]), app_module.MAX_JSON_STRING_LENGTH)
        self.assertTrue(safe_value["long"].endswith("…"))
        self.assertLessEqual(len(safe_value["nested"][0]), app_module.MAX_JSON_STRING_LENGTH)
        self.assertTrue(safe_value["nested"][0].endswith("…"))

