    def test_normalizers_accept_read_only_mapping_values(self):
        summary = app_module.normalize_format_summary(
            MappingProxyType(
                {
                    "stats": MappingProxyType({"heading_l1": "2"}),
                    "page_setup": MappingProxyType(
                        {
                            "page_size": "A4",
                            "margins_cm": MappingProxyType({"top": "2.5"}),
                        }
                    ),
                    "outline": (MappingProxyType({"level": "h1", "text": "标题"}),),
                    "cover_generated": True,
                }
            )
        )
        safe_value = app_module.make_json_safe(
            MappingProxyType({"outer": MappingProxyType({"bad": object(), "ok": "yes"})})
        )

        self.assertEqual(summary["stats"]["heading_l1"], 2)
        self.assertEqual(summary["page_setup"]["margins_cm"]["top"], 2.5)
        self.assertEqual(summary["outline"], [{"level": "h1", "text": "标题"}])
        self.assertIs(summary["cover_generated"], True)
        self.assertEqual(safe_value, {"outer": {"bad": None, "ok": "yes"}})

