    def test_download_rejects_inode_replaced_between_stat_and_open(self):
        generated_output = self.output_dir / TEST_OUTPUT_FILENAME
        generated_output.write_bytes(b"original-output")
        original_open = app_module.os.open
        replaced = False

        def replace_before_file_open(path, flags, *args, **kwargs):
            nonlocal replaced
            if path == TEST_OUTPUT_FILENAME and not replaced:
                replaced = True
                generated_output.unlink()
                generated_output.write_bytes(b"replacement-output")
            return original_open(path, flags, *args, **kwargs)

        with patch.object(app_module.os, "open", side_effect=replace_before_file_open):
            response = self.client.get(TEST_DOWNLOAD_URL)

        self.assertTrue(replaced)
        self.assertEqual(response.status_code, 404)
        self.assertEqual(
            response.get_json(),
            {"success": False, "error": "文件不存在或已过期"},
        )
        with app_module.OUTPUT_STORAGE_LOCK:
            self.assertNotIn(generated_output, app_module.ACTIVE_OUTPUT_DOWNLOADS)

