    def test_download_supports_single_and_suffix_byte_ranges(self):
        generated_output = self.output_dir / TEST_OUTPUT_FILENAME
        generated_output.write_bytes(b"0123456789")

        range_response = self.client.get(
            TEST_DOWNLOAD_URL,
            headers={"Range": "bytes=2-5"},
            buffered=False,
        )
        try:
            self.assertEqual(range_response.status_code, 206)
            self.assertEqual(range_response.get_data(), b"2345")
            self.assertEqual(range_response.headers.get("Content-Length"), "4")
            self.assertEqual(range_response.headers.get("Content-Range"), "bytes 2-5/10")
            self.assertEqual(range_response.headers.get("Accept-Ranges"), "bytes")
            self.assertEqual(range_response.headers.get("Cache-Control"), "no-store")
            self.assertIsNone(range_response.headers.get("ETag"))
            self.assertIsNone(range_response.headers.get("Last-Modified"))
        finally:
            range_response.close()

        suffix_response = self.client.get(
            TEST_DOWNLOAD_URL,
            headers={"Range": "bytes=-3"},
            buffered=False,
        )
        try:
            self.assertEqual(suffix_response.status_code, 206)
            self.assertEqual(suffix_response.get_data(), b"789")
            self.assertEqual(suffix_response.headers.get("Content-Length"), "3")
            self.assertEqual(suffix_response.headers.get("Content-Range"), "bytes 7-9/10")
            self.assertEqual(suffix_response.headers.get("Accept-Ranges"), "bytes")
        finally:
            suffix_response.close()

        open_ended_response = self.client.get(
            TEST_DOWNLOAD_URL,
            headers={"Range": "bytes=6-"},
            buffered=False,
        )
        try:
            self.assertEqual(open_ended_response.status_code, 206)
            self.assertEqual(open_ended_response.get_data(), b"6789")
            self.assertEqual(open_ended_response.headers.get("Content-Length"), "4")
            self.assertEqual(
                open_ended_response.headers.get("Content-Range"),
                "bytes 6-9/10",
            )
        finally:
            open_ended_response.close()

