    def test_download_lease_protects_ttl_and_capacity_then_keeps_retry_window(self):
        generated_output = self.output_dir / TEST_OUTPUT_FILENAME
        generated_output.write_bytes(b"data")
        response = self.client.get(TEST_DOWNLOAD_URL, buffered=False)

        try:
            with app_module.OUTPUT_STORAGE_LOCK:
                self.assertEqual(app_module.ACTIVE_OUTPUT_DOWNLOADS.get(generated_output), 1)
            self.assertEqual(
                app_module.get_output_storage_snapshot()["active_downloads"],
                1,
            )

            old_timestamp = app_module.time.time() - 120
            os.utime(generated_output, (old_timestamp, old_timestamp))
            with app_module.OUTPUT_STORAGE_LOCK:
                app_module.RECENT_OUTPUT_REQUESTS[generated_output] = old_timestamp

            app_module.cleanup_expired_files(self.output_dir, max_age_seconds=60)
            self.assertTrue(generated_output.exists())

            with patch.multiple(
                app_module,
                MAX_OUTPUT_STORAGE_BYTES=0,
                MAX_OUTPUT_STORAGE_FILES=0,
                MIN_OUTPUT_FREE_BYTES=0,
                MIN_OUTPUT_RETENTION_SECONDS=0,
            ):
                with self.assertRaises(app_module.JobProcessingError):
                    app_module.enforce_output_storage_budget()

            self.assertTrue(generated_output.exists())
            before_close = app_module.time.time()
        finally:
            response.close()

        with app_module.OUTPUT_STORAGE_LOCK:
            self.assertNotIn(generated_output, app_module.ACTIVE_OUTPUT_DOWNLOADS)
            requested_at = app_module.RECENT_OUTPUT_REQUESTS.get(generated_output)
        self.assertEqual(app_module.get_output_storage_snapshot()["active_downloads"], 0)
        self.assertIsInstance(requested_at, (int, float))
        self.assertGreaterEqual(requested_at, before_close)
        self.assertGreater(
            requested_at,
            app_module.time.time() - app_module.MIN_REQUESTED_TERMINAL_RETENTION_SECONDS,
        )

        app_module.cleanup_expired_files(self.output_dir, max_age_seconds=0)
        self.assertTrue(generated_output.exists())

