    def test_download_large_offset_range_seeks_even_with_nonseekable_server_wrapper(self):
        generated_output = self.output_dir / TEST_OUTPUT_FILENAME
        content = b"x" * (1024 * 1024 - 4) + b"tail"
        generated_output.write_bytes(content)
        original_fdopen = app_module.os.fdopen
        observed = {}

        class CountingFile:
            def __init__(self, wrapped):
                self._wrapped = wrapped
                self.bytes_read = 0

            def read(self, *args, **kwargs):
                data = self._wrapped.read(*args, **kwargs)
                self.bytes_read += len(data)
                return data

            def __getattr__(self, name):
                return getattr(self._wrapped, name)

        class NonSeekableServerWrapper:
            def __init__(self, file, buffer_size=8192):
                self.file = file
                self.buffer_size = buffer_size

            def __iter__(self):
                return self

            def __next__(self):
                data = self.file.read(self.buffer_size)
                if data:
                    return data
                raise StopIteration

            def close(self):
                self.file.close()

        def counting_fdopen(*args, **kwargs):
            counting_file = CountingFile(original_fdopen(*args, **kwargs))
            observed["file"] = counting_file
            return counting_file

        with patch.object(app_module.os, "fdopen", side_effect=counting_fdopen):
            response = self.client.get(
                TEST_DOWNLOAD_URL,
                headers={"Range": f"bytes={len(content) - 4}-"},
                environ_overrides={"wsgi.file_wrapper": NonSeekableServerWrapper},
                buffered=False,
            )
        try:
            self.assertEqual(response.status_code, 206)
            self.assertEqual(response.get_data(), b"tail")
        finally:
            response.close()

        self.assertEqual(observed["file"].bytes_read, 4)

    def test_download_exception_cleanup_releases_even_if_response_close_fails(self):
        released = []

        class BrokenResponse:
            def close(self):
                raise OSError("close failed")

        app_module.close_output_download_response(
            BrokenResponse(),
            lambda: released.append(True),
        )

        self.assertEqual(released, [True])

    def test_download_response_close_failure_still_releases_active_lease(self):
        generated_output = self.output_dir / TEST_OUTPUT_FILENAME
        generated_output.write_bytes(b"download-body")
        original_send_file = app_module.send_file
        leased_files = []

        class BrokenCloseIterable:
            def __init__(self, iterable):
                self._iterator = iter(iterable)

            def __iter__(self):
                return self

            def __next__(self):
                return next(self._iterator)

            def close(self):
                raise OSError("iterable close failed")

        def send_with_broken_close(download_file, *args, **kwargs):
            leased_files.append(download_file)
            response = original_send_file(download_file, *args, **kwargs)
            response.response = BrokenCloseIterable(response.response)
            return response

        with patch.object(app_module, "send_file", side_effect=send_with_broken_close):
            response = self.client.get(TEST_DOWNLOAD_URL, buffered=False)

        with app_module.OUTPUT_STORAGE_LOCK:
            self.assertEqual(app_module.ACTIVE_OUTPUT_DOWNLOADS.get(generated_output), 1)
        response.close()
        with app_module.OUTPUT_STORAGE_LOCK:
            self.assertNotIn(generated_output, app_module.ACTIVE_OUTPUT_DOWNLOADS)
        self.assertEqual(len(leased_files), 1)
        self.assertTrue(leased_files[0].closed)

