    def test_text_endpoints_reject_xml_incompatible_characters_before_formatting(self):
        # JSON escapes allow Flask to decode these values into Python strings
        # without the test client's UTF-8 encoder rejecting them first.
        for value in ("\ud800", "\x00", "\x08", "\ufffe", "\uffff"):
            with self.subTest(codepoint=f"U+{ord(value):04X}"):
                body = json.dumps({"text": value}).encode("utf-8")
                for endpoint in ("/api/format_text", "/api/format_text_async"):
                    with self.subTest(endpoint=endpoint):
                        response = self.client.post(
                            endpoint,
                            data=body,
                            content_type="application/json",
                        )

                        self.assertEqual(response.status_code, 400)
                        self.assertEqual(
                            response.get_json(),
                            {
                                "success": False,
                                "error": app_module.TEXT_INVALID_CHARACTERS_MESSAGE,
                            },
                        )
                        self.assertEqual(app_module.PROGRESS_JOBS, {})
                        self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])

