    def test_text_endpoints_accept_exact_paragraph_limit_with_stub_processors(self):
        exact_limit_text = "\n".join(["x"] * app_module.MAX_TEXT_PARAGRAPHS)

        for endpoint, expected_status in (
            ("/api/format_text", 200),
            ("/api/format_text_async", 202),
        ):
            with self.subTest(endpoint=endpoint):
                app_module.PROGRESS_JOBS.clear()
                app_module.PROCESSING_JOB_SLOTS = app_module.threading.BoundedSemaphore(1)

                def stub_processor(text, job_id, **_kwargs):
                    return {"success": True, "job_id": job_id}

                def run_inline(_job, _task_name, work_fn, **_kwargs):
                    with app_module.processing_job_slot():
                        return work_fn(lambda *_args, **_kwargs: None)

                with (
                    patch.object(
                        app_module,
                        "process_text_document",
                        side_effect=stub_processor,
                    ) as processor,
                    patch.object(
                        app_module,
                        "launch_background_job",
                        side_effect=run_inline,
                    ) as launcher,
                ):
                    response = self.client.post(
                        endpoint,
                        json={"text": exact_limit_text},
                    )

                self.assertEqual(response.status_code, expected_status)
                self.assertTrue(response.get_json()["success"])
                self.assertIsNone(response.headers.get("Connection"))
                processor.assert_called_once()
                self.assertEqual(processor.call_args.args[0], exact_limit_text)
                if endpoint.endswith("_async"):
                    launcher.assert_called_once()
                    self.assertEqual(
                        set(app_module.PROGRESS_JOBS),
                        {processor.call_args.args[1]},
                    )
                else:
                    launcher.assert_not_called()
                    self.assertEqual(app_module.PROGRESS_JOBS, {})
                self.assertEqual(list(self.output_dir.glob("*")), [])

                with app_module.processing_job_slot():
                    pass

