    def test_cleanup_expired_jobs_retains_hard_linked_terminal_output(self):
        job, created = app_module.get_or_create_progress_job(
            "format_text",
            TEST_JOB_ID,
        )
        self.assertTrue(created)
        job["status"] = "done"
        job["updated_at"] = app_module.time.time() - 120
        output_path = self.output_dir / TEST_OUTPUT_FILENAME
        source_path = Path(self.temp_dir.name) / "externally-owned.docx"
        source_path.write_bytes(b"externally-owned-output")
        try:
            os.link(source_path, output_path)
        except (AttributeError, OSError) as exc:
            self.skipTest(f"hard links unavailable: {exc}")

        app_module.cleanup_expired_jobs(max_age_seconds=60)

        # Capacity/TTL cleanup must not remove a generated name that shares an
        # inode with an externally owned path; retaining the job keeps the
        # output discoverable for a later explicit cleanup decision.
        self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
        self.assertTrue(output_path.exists())
        self.assertEqual(source_path.read_bytes(), b"externally-owned-output")

    def test_cleanup_expired_jobs_retains_job_while_output_download_is_leased(self):
        job, _created = app_module.get_or_create_progress_job(
            "format_text",
            TEST_JOB_ID,
        )
        job["status"] = "done"
        job["updated_at"] = app_module.time.time() - 120
        output_path = self.output_dir / TEST_OUTPUT_FILENAME
        output_path.write_bytes(b"leased-output-for-stale-job")
        lease = app_module.acquire_output_download_lease(output_path)
        self.assertIsNotNone(lease)
        release_download, _download_file, _file_size = lease

        try:
            app_module.cleanup_expired_jobs(max_age_seconds=60)

            self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
            self.assertTrue(output_path.exists())
        finally:
            release_download()

        # 关闭下载会刷新断线重试保护窗；租约刚释放时
        # 仍不能删除 job 或输出。
        app_module.cleanup_expired_jobs(max_age_seconds=60)
        self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
        self.assertTrue(output_path.exists())

        with app_module.OUTPUT_STORAGE_LOCK:
            app_module.RECENT_OUTPUT_REQUESTS[output_path] = (
                app_module.time.time()
                - app_module.MIN_REQUESTED_TERMINAL_RETENTION_SECONDS
                - 1
            )
        app_module.cleanup_expired_jobs(max_age_seconds=60)

        self.assertNotIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
        self.assertFalse(output_path.exists())

