    def test_cleanup_expired_jobs_waits_for_inflight_result_request(self):
        job, _created = app_module.get_or_create_progress_job(
            "format_text",
            TEST_JOB_ID,
        )
        job["status"] = "done"
        job["updated_at"] = app_module.time.time() - 120
        output_path = self.output_dir / TEST_OUTPUT_FILENAME
        output_path.write_bytes(b"ttl-result-being-requested")
        request_holds_guard = app_module.threading.Event()
        results = {}

        class TrackingGuardLock:
            def __init__(self):
                self._lock = app_module.threading.Lock()

            def __enter__(self):
                self._lock.acquire()
                if app_module.threading.current_thread().name == "result-requester":
                    request_holds_guard.set()
                return self

            def __exit__(self, exc_type, exc_value, traceback):
                self._lock.release()

        def request_result():
            results["snapshot"] = app_module.get_progress_job_result_snapshot(
                TEST_JOB_ID
            )

        requester = app_module.threading.Thread(
            target=request_result,
            name="result-requester",
        )
        cleaner = app_module.threading.Thread(
            target=app_module.cleanup_expired_jobs,
            kwargs={"max_age_seconds": 60},
            name="job-expiry-cleaner",
        )
        with patch.object(
            app_module,
            "OUTPUT_RESULT_GUARD_LOCK",
            TrackingGuardLock(),
        ):
            with app_module.PROGRESS_JOBS_LOCK:
                requester.start()
                self.assertTrue(request_holds_guard.wait(timeout=5))
                cleaner.start()
                self.assertTrue(cleaner.is_alive())
                self.assertTrue(output_path.exists())

            requester.join(timeout=5)
            cleaner.join(timeout=5)

        self.assertFalse(requester.is_alive())
        self.assertFalse(cleaner.is_alive())
        self.assertIsNotNone(results.get("snapshot"))
        self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
        self.assertTrue(output_path.exists())

