    def test_capacity_pruning_waits_for_inflight_result_request(self):
        original_limit = app_module.MAX_PROGRESS_JOBS
        request_holds_guard = app_module.threading.Event()
        pruner_waits_for_guard = app_module.threading.Event()
        results = {}

        class TrackingGuardLock:
            def __init__(self):
                self._lock = app_module.threading.Lock()

            def __enter__(self):
                if app_module.threading.current_thread().name == "capacity-pruner":
                    pruner_waits_for_guard.set()
                self._lock.acquire()
                if app_module.threading.current_thread().name == "result-requester":
                    request_holds_guard.set()
                return self

            def __exit__(self, exc_type, exc_value, traceback):
                self._lock.release()

        app_module.MAX_PROGRESS_JOBS = 1
        try:
            requested_done = app_module.create_progress_job("format_text")
            requested_done["status"] = "done"
            requested_done["updated_at"] = (
                app_module.time.time() - app_module.MIN_UNREAD_TERMINAL_RETENTION_SECONDS - 1
            )
            output_path = self.output_dir / f"{requested_done['id']}_output.docx"
            output_path.write_bytes(b"result-being-requested")

            def request_result():
                results["snapshot"] = app_module.get_progress_job_result_snapshot(
                    requested_done["id"]
                )

            def create_at_capacity():
                try:
                    app_module.create_progress_job("format_text")
                except app_module.JobProcessingError as exc:
                    results["error"] = exc

            requester = app_module.threading.Thread(
                target=request_result,
                name="result-requester",
            )
            pruner = app_module.threading.Thread(
                target=create_at_capacity,
                name="capacity-pruner",
            )
            tracking_guard = TrackingGuardLock()
            with patch.object(
                app_module,
                "OUTPUT_RESULT_GUARD_LOCK",
                tracking_guard,
            ):
                with app_module.PROGRESS_JOBS_LOCK:
                    requester.start()
                    self.assertTrue(request_holds_guard.wait(timeout=5))
                    pruner.start()
                    self.assertTrue(pruner_waits_for_guard.wait(timeout=5))
                    self.assertTrue(pruner.is_alive())
                    self.assertTrue(output_path.exists())

                requester.join(timeout=5)
                pruner.join(timeout=5)

            self.assertFalse(requester.is_alive())
            self.assertFalse(pruner.is_alive())
            self.assertIsNotNone(results.get("snapshot"))
            self.assertEqual(results["error"].status_code, 503)
            self.assertIn(requested_done["id"], app_module.PROGRESS_JOBS)
            self.assertTrue(output_path.exists())
        finally:
            app_module.MAX_PROGRESS_JOBS = original_limit

