    def test_capacity_pruning_retains_job_while_output_download_is_leased(self):
        original_limit = app_module.MAX_PROGRESS_JOBS
        app_module.MAX_PROGRESS_JOBS = 1
        output_path = self.output_dir / TEST_OUTPUT_FILENAME
        release_download = None
        try:
            stale_job, _created = app_module.get_or_create_progress_job(
                "format_text",
                TEST_JOB_ID,
            )
            stale_job["status"] = "done"
            stale_job["updated_at"] = (
                app_module.time.time()
                - app_module.MIN_UNREAD_TERMINAL_RETENTION_SECONDS
                - 1
            )
            output_path.write_bytes(b"leased-terminal-output")
            lease = app_module.acquire_output_download_lease(output_path)
            self.assertIsNotNone(lease)
            release_download, _download_file, _file_size = lease

            with self.assertRaises(app_module.JobProcessingError) as caught:
                app_module.create_progress_job("format_text")

            self.assertEqual(caught.exception.status_code, 503)
            self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
            self.assertTrue(output_path.exists())

            release_download()
            release_download = None

            # 租约关闭后的重试窗也必须阻止容量淘汰。
            with self.assertRaises(app_module.JobProcessingError) as caught:
                app_module.create_progress_job("format_text")

            self.assertEqual(caught.exception.status_code, 503)
            self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
            self.assertTrue(output_path.exists())

            with app_module.OUTPUT_STORAGE_LOCK:
                app_module.RECENT_OUTPUT_REQUESTS[output_path] = (
                    app_module.time.time()
                    - app_module.MIN_REQUESTED_TERMINAL_RETENTION_SECONDS
                    - 1
                )

            replacement = app_module.create_progress_job("format_text")

            self.assertNotIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
            self.assertIn(replacement["id"], app_module.PROGRESS_JOBS)
            self.assertFalse(output_path.exists())
        finally:
            if release_download is not None:
                release_download()
            app_module.MAX_PROGRESS_JOBS = original_limit

    def test_capacity_pruning_retains_job_while_output_is_reserved(self):
        original_limit = app_module.MAX_PROGRESS_JOBS
        app_module.MAX_PROGRESS_JOBS = 1
        output_path = self.output_dir / TEST_OUTPUT_FILENAME
        release_reservation = None
        try:
            stale_job, _created = app_module.get_or_create_progress_job(
                "format_text",
                TEST_JOB_ID,
            )
            stale_job["status"] = "done"
            stale_job["updated_at"] = (
                app_module.time.time()
                - app_module.MIN_UNREAD_TERMINAL_RETENTION_SECONDS
                - 1
            )
            release_reservation = app_module.reserve_output_storage(
                output_path,
                reserved_bytes=4,
            )

            with self.assertRaises(app_module.JobProcessingError) as caught:
                app_module.create_progress_job("format_text")

            self.assertEqual(caught.exception.status_code, 503)
            self.assertIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
            self.assertIn(output_path, app_module.ACTIVE_OUTPUT_RESERVATIONS)

            release_reservation()
            release_reservation = None
            replacement = app_module.create_progress_job("format_text")

            self.assertNotIn(TEST_JOB_ID, app_module.PROGRESS_JOBS)
            self.assertIn(replacement["id"], app_module.PROGRESS_JOBS)
        finally:
            if release_reservation is not None:
                release_reservation()
            app_module.MAX_PROGRESS_JOBS = original_limit

    def test_capacity_pruning_waits_for_consistent_completion_timestamp(self):
        original_limit = app_module.MAX_PROGRESS_JOBS
        original_retention = app_module.MIN_UNREAD_TERMINAL_RETENTION_SECONDS
        completion_paused = app_module.threading.Event()
        prune_snapshot_attempted = app_module.threading.Event()
        allow_completion = app_module.threading.Event()
        created_job_holder = {}

        class TrackingCondition(app_module.threading.Condition):
            def __enter__(self):
                if app_module.threading.current_thread().name == "capacity-pruner":
                    prune_snapshot_attempted.set()
                return super().__enter__()

        class PausingJob(dict):
            def __setitem__(self, key, value):
                super().__setitem__(key, value)
                if key == "status" and value == "done":
                    completion_paused.set()
                    allow_completion.wait(timeout=5)

        app_module.MAX_PROGRESS_JOBS = 3
        app_module.MIN_UNREAD_TERMINAL_RETENTION_SECONDS = 0
        try:
            old_done = app_module.create_progress_job("format_text")
            completing_original = app_module.create_progress_job("format_text")
            active = app_module.create_progress_job("format_text")
            old_done["status"] = "done"
            old_done["updated_at"] = app_module.time.time() - 120
            completing_original["updated_at"] = app_module.time.time() - 240

            completing = PausingJob(completing_original)
            completing["condition"] = TrackingCondition()
            with app_module.PROGRESS_JOBS_LOCK:
                app_module.PROGRESS_JOBS[completing["id"]] = completing

            completion_worker = app_module.threading.Thread(
                target=app_module.complete_progress_job,
                args=(completing, {"success": True}),
                name="completion-writer",
            )

            def create_at_capacity():
                created_job_holder["job"] = app_module.create_progress_job("format_text")

            prune_worker = app_module.threading.Thread(
                target=create_at_capacity,
                name="capacity-pruner",
            )
            try:
                completion_worker.start()
                self.assertTrue(completion_paused.wait(timeout=5))
                prune_worker.start()
                self.assertTrue(prune_snapshot_attempted.wait(timeout=5))
                self.assertTrue(prune_worker.is_alive())
            finally:
                allow_completion.set()
                completion_worker.join(timeout=5)
                prune_worker.join(timeout=5)

            self.assertFalse(completion_worker.is_alive())
            self.assertFalse(prune_worker.is_alive())
            self.assertNotIn(old_done["id"], app_module.PROGRESS_JOBS)
            self.assertIn(completing["id"], app_module.PROGRESS_JOBS)
            self.assertIn(active["id"], app_module.PROGRESS_JOBS)
            self.assertIn(created_job_holder["job"]["id"], app_module.PROGRESS_JOBS)
        finally:
            allow_completion.set()
            app_module.MAX_PROGRESS_JOBS = original_limit
            app_module.MIN_UNREAD_TERMINAL_RETENTION_SECONDS = original_retention

    def test_create_progress_job_rejects_when_active_jobs_reach_capacity(self):
        original_limit = app_module.MAX_PROGRESS_JOBS
        app_module.MAX_PROGRESS_JOBS = 2
