    def test_cleanup_expired_files_removes_old_files_and_empty_directories(self):
        old_file = self.upload_dir / "old_input.docx"
        old_file.write_bytes(b"old")
        old_empty_dir = self.upload_dir / "old_output.docx"
        old_empty_dir.mkdir()
        old_nonempty_dir = self.upload_dir / "old_nonempty.docx"
        old_nonempty_dir.mkdir()
        child_file = old_nonempty_dir / "child.txt"
        child_file.write_text("keep", encoding="utf-8")
        old_broken_symlink = self.upload_dir / "old_link.docx"
        old_broken_symlink.symlink_to(self.upload_dir / "missing-target.docx")
        fresh_file = self.upload_dir / "fresh_input.docx"
        fresh_file.write_bytes(b"fresh")

        old_timestamp = app_module.time.time() - 120
        for path in (old_file, old_empty_dir, old_nonempty_dir):
            os.utime(path, (old_timestamp, old_timestamp))
        os.utime(old_broken_symlink, (old_timestamp, old_timestamp), follow_symlinks=False)

        app_module.cleanup_expired_files(self.upload_dir, max_age_seconds=60)

        self.assertFalse(old_file.exists())
        self.assertFalse(old_empty_dir.exists())
        self.assertFalse(old_broken_symlink.exists())
        self.assertFalse(old_broken_symlink.is_symlink())
        self.assertTrue(old_nonempty_dir.exists())
        self.assertTrue(child_file.exists())
        self.assertTrue(fresh_file.exists())

