    def test_cleanup_expired_files_rechecks_upload_lease_after_stale_snapshot(self):
        active_path = self.upload_dir / f"{TEST_JOB_ID}_input.docx"
        original_glob = Path.glob
        upload_created = False

        def create_upload_before_docx_scan(folder, pattern):
            nonlocal upload_created
            if folder == self.upload_dir and pattern == "*.docx" and not upload_created:
                upload_created = True
                app_module.save_uploaded_file(
                    FileStorage(stream=BytesIO(b"active-upload"), filename="input.docx"),
                    active_path,
                )
                old_timestamp = app_module.time.time() - 120
                os.utime(active_path, (old_timestamp, old_timestamp))
            return original_glob(folder, pattern)

        # cleanup_expired_files() 已获取活动路径快照后才创建上传
        # 副本；删除前必须在存储锁内重新检查实时租约。
        with patch.object(Path, "glob", create_upload_before_docx_scan):
            app_module.cleanup_expired_files(self.upload_dir, max_age_seconds=60)

        self.assertTrue(upload_created)
        self.assertTrue(active_path.exists())
        self.assertIn(active_path, app_module.ACTIVE_TEMP_FILES)
        app_module.cleanup_path(active_path)

