    def test_cleanup_expired_files_ignores_directory_iteration_errors(self):
        old_file = self.upload_dir / "old_input.docx"
        old_file.write_bytes(b"old")
        old_timestamp = app_module.time.time() - 120
        os.utime(old_file, (old_timestamp, old_timestamp))

        path_class = type(self.upload_dir)
        original_glob = path_class.glob

        def failing_glob(path, pattern):
            if path == self.upload_dir:
                raise OSError("permission denied")
            return original_glob(path, pattern)

        # PosixPath 通常从 Path 继承 glob；patch.object 会在结束时
        # 删除临时子类属性，避免把一份旧函数永久留在子类上。
        with patch.object(path_class, "glob", failing_glob):
            app_module.cleanup_expired_files(self.upload_dir, max_age_seconds=60)

        self.assertTrue(old_file.exists())

