    def test_result_request_serializes_output_protection_with_ttl_and_capacity_eviction(self):
        for eviction_kind in ("ttl", "capacity"):
            with self.subTest(eviction_kind=eviction_kind):
                app_module.PROGRESS_JOBS.clear()
                with app_module.OUTPUT_STORAGE_LOCK:
                    app_module.RECENT_OUTPUT_REQUESTS.clear()
                for existing_path in self.output_dir.glob("*.docx"):
                    existing_path.unlink()

                job = app_module.create_progress_job("format")
                app_module.complete_progress_job(job, {"success": True})
                output_path = self.output_dir / f"{job['id']}_output.docx"
                output_path.write_bytes(b"data")
                old_timestamp = app_module.time.time() - 120
                os.utime(output_path, (old_timestamp, old_timestamp))

                record_started = app_module.threading.Event()
                allow_record = app_module.threading.Event()
                eviction_lock_attempted = app_module.threading.Event()
                results = {}
                cleaner_name = f"{eviction_kind}-output-cleaner"

                class TrackingGuardLock:
                    def __init__(self):
                        self._lock = app_module.threading.Lock()

                    def __enter__(self):
                        if app_module.threading.current_thread().name == cleaner_name:
                            eviction_lock_attempted.set()
                        self._lock.acquire()
                        return self

                    def __exit__(self, exc_type, exc_value, traceback):
                        self._lock.release()

                original_record_requested_output = app_module.record_requested_output

                def delayed_record_requested_output(job_id, protect_output, now):
                    record_started.set()
                    if not allow_record.wait(timeout=5):
                        raise RuntimeError("timed out waiting to record output protection")
                    return original_record_requested_output(job_id, protect_output, now)

                def request_result():
                    try:
                        results["snapshot"] = app_module.get_progress_job_result_snapshot(job["id"])
                    except BaseException as exc:  # pragma: no cover - thread failure assertion below
                        results["request_error"] = exc

                def evict_output():
                    try:
                        if eviction_kind == "ttl":
                            app_module.cleanup_expired_files(
                                self.output_dir,
                                max_age_seconds=60,
                            )
                        else:
                            with patch.multiple(
                                app_module,
                                MAX_OUTPUT_STORAGE_BYTES=3,
                                MAX_OUTPUT_STORAGE_FILES=10,
                                MIN_OUTPUT_FREE_BYTES=0,
                                MIN_OUTPUT_RETENTION_SECONDS=0,
                            ):
                                try:
                                    app_module.enforce_output_storage_budget()
                                except app_module.JobProcessingError as exc:
                                    results["capacity_status"] = exc.status_code
                    except BaseException as exc:  # pragma: no cover - thread failure assertion below
                        results["eviction_error"] = exc

                tracking_guard = TrackingGuardLock()
                requester = app_module.threading.Thread(
                    target=request_result,
                    name=f"{eviction_kind}-result-requester",
                )
                cleaner = app_module.threading.Thread(
                    target=evict_output,
                    name=cleaner_name,
                )
                with (
                    patch.object(app_module, "OUTPUT_RESULT_GUARD_LOCK", tracking_guard),
                    patch.object(
                        app_module,
                        "record_requested_output",
                        side_effect=delayed_record_requested_output,
                    ),
                ):
                    requester.start()
                    self.assertTrue(record_started.wait(timeout=5))
                    self.assertIsInstance(job["result_requested_at"], float)

                    cleaner.start()
                    self.assertTrue(eviction_lock_attempted.wait(timeout=5))
                    self.assertTrue(cleaner.is_alive())
                    self.assertTrue(output_path.exists())

                    allow_record.set()
                    requester.join(timeout=5)
                    cleaner.join(timeout=5)

                self.assertFalse(requester.is_alive())
                self.assertFalse(cleaner.is_alive())
                self.assertNotIn("request_error", results)
                self.assertNotIn("eviction_error", results)
                self.assertIsNotNone(results.get("snapshot"))
                if eviction_kind == "capacity":
                    self.assertEqual(results.get("capacity_status"), 503)
                self.assertTrue(output_path.exists())

