    def test_output_storage_budget_prefers_requested_result_over_unread_result(self):
        requested_job = app_module.create_progress_job("format")
        unread_job = app_module.create_progress_job("format")
        app_module.complete_progress_job(requested_job, {"success": True})
        app_module.complete_progress_job(unread_job, {"success": True})
        app_module.mark_progress_job_result_requested(requested_job)
        with requested_job["condition"]:
            requested_job["result_requested_at"] = (
                app_module.time.time() - app_module.MIN_REQUESTED_TERMINAL_RETENTION_SECONDS - 1
            )
        requested_output = self.output_dir / f"{requested_job['id']}_output.docx"
        unread_output = self.output_dir / f"{unread_job['id']}_output.docx"
        with app_module.OUTPUT_STORAGE_LOCK:
            app_module.RECENT_OUTPUT_REQUESTS[requested_output] = requested_job[
                "result_requested_at"
            ]
        old_timestamp = app_module.time.time() - 120
        for path in (requested_output, unread_output):
            path.write_bytes(b"data")
            os.utime(path, (old_timestamp, old_timestamp))

        with patch.multiple(
            app_module,
            MAX_OUTPUT_STORAGE_BYTES=4,
            MAX_OUTPUT_STORAGE_FILES=1,
            MIN_OUTPUT_FREE_BYTES=0,
            MIN_OUTPUT_RETENTION_SECONDS=0,
        ):
            app_module.enforce_output_storage_budget()

        self.assertFalse(requested_output.exists())
        self.assertTrue(unread_output.exists())

