    def test_output_storage_reservations_prevent_concurrent_overcommit(self):
        paths = [
            self.output_dir / TEST_OUTPUT_FILENAME,
            self.output_dir / OTHER_OUTPUT_FILENAME,
            self.output_dir / f"{'a' * app_module.JOB_ID_LENGTH}_output.docx",
        ]
        release_gate = app_module.threading.Event()
        outcomes = []
        outcomes_lock = app_module.threading.Lock()

        def reserve(path):
            release = None
            try:
                release = app_module.reserve_output_storage(path, reserved_bytes=4)
                outcome = "reserved"
            except app_module.JobProcessingError:
                outcome = "rejected"
            with outcomes_lock:
                outcomes.append(outcome)
            if release is not None:
                release_gate.wait(timeout=5)
                release()

        with patch.multiple(
            app_module,
            MAX_OUTPUT_STORAGE_BYTES=8,
            MAX_OUTPUT_STORAGE_FILES=10,
            MIN_OUTPUT_FREE_BYTES=0,
            MIN_OUTPUT_RETENTION_SECONDS=0,
        ):
            workers = [
                app_module.threading.Thread(target=reserve, args=(path,))
                for path in paths
            ]
            try:
                for worker in workers:
                    worker.start()
                deadline = app_module.time.time() + 5
                while len(outcomes) < len(workers) and app_module.time.time() < deadline:
                    app_module.time.sleep(0.01)
                self.assertEqual(sorted(outcomes), ["rejected", "reserved", "reserved"])
            finally:
                release_gate.set()
                for worker in workers:
                    worker.join(timeout=5)

        self.assertTrue(all(not worker.is_alive() for worker in workers))
        self.assertEqual(app_module.ACTIVE_OUTPUT_RESERVATIONS, {})

