    def test_background_job_limit_rejects_excess_request_and_recovers(self):
        app_module.PROCESSING_JOB_SLOTS = app_module.threading.BoundedSemaphore(1)
        blocker_job = app_module.create_progress_job("format_text")
        blocker_started = app_module.threading.Event()
        release_blocker = app_module.threading.Event()

        def blocking_work(_progress_callback):
            blocker_started.set()
            release_blocker.wait()
            return {"success": True}

        blocker_worker = app_module.launch_background_job(
            blocker_job,
            "并发限制测试任务",
            blocking_work,
        )
        try:
            self.assertTrue(blocker_started.wait(timeout=5))
            with (
                patch.object(
                    app_module,
                    "get_single_uploaded_file",
                    side_effect=AssertionError("busy requests must not parse multipart bodies"),
                ) as multipart_parser,
                patch.object(
                    app_module,
                    "reserve_upload_storage",
                    side_effect=AssertionError("busy requests must not reserve upload storage"),
                ) as upload_reserver,
            ):
                response = self.client.post(
                    "/api/format_async",
                    data={"file": (BytesIO(self.test_doc_bytes), "test_input.docx")},
                    content_type="multipart/form-data",
                )
                multipart_parser.assert_not_called()
                upload_reserver.assert_not_called()

            self.assertEqual(response.status_code, 503)
            self.assertEqual(
                response.get_json(),
                {"success": False, "error": "当前任务较多，请稍后重试。"},
            )
            self.assertEqual(set(app_module.PROGRESS_JOBS), {blocker_job["id"]})
            self.assertEqual(list(self.upload_dir.glob("*.docx")), [])
            self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
        finally:
            release_blocker.set()
            blocker_worker.join(timeout=5)

        self.assertFalse(blocker_worker.is_alive())
        self.assertEqual(blocker_job["status"], "done")

        recovery_job = app_module.create_progress_job("format_text")
        recovery_worker = app_module.launch_background_job(
            recovery_job,
            "并发限制恢复测试任务",
            lambda _progress_callback: {"success": True},
        )
        recovery_worker.join(timeout=5)

        self.assertFalse(recovery_worker.is_alive())
        self.assertEqual(recovery_job["status"], "done")

    def test_async_request_transfers_its_pre_reserved_slot_to_worker(self):
        app_module.PROCESSING_JOB_SLOTS = app_module.threading.BoundedSemaphore(1)
        worker_started = app_module.threading.Event()
        release_worker = app_module.threading.Event()

        def blocking_processor(_text, job_id, **_kwargs):
            worker_started.set()
            release_worker.wait(timeout=5)
            return {"success": True, "job_id": job_id}

        try:
            with patch.object(app_module, "process_text_document", side_effect=blocking_processor):
                first_response = self.client.post(
                    "/api/format_text_async",
                    json={"text": "论文标题\n正文内容"},
                )
                self.assertEqual(first_response.status_code, 202)
                self.assertTrue(worker_started.wait(timeout=5))

                with patch.object(
                    app_module,
                    "get_request_payload",
                    side_effect=AssertionError("busy requests must not parse JSON bodies"),
                ) as payload_parser:
                    second_response = self.client.post(
                        "/api/format_text_async",
                        json={"text": "另一个任务"},
                    )
                    payload_parser.assert_not_called()

                self.assertEqual(second_response.status_code, 503)
                self.assertEqual(
                    second_response.get_json(),
                    {"success": False, "error": "当前任务较多，请稍后重试。"},
                )
        finally:
            release_worker.set()

        deadline = app_module.time.time() + 5
        while True:
            try:
                recovered_slots = app_module.acquire_processing_job_slot()
            except app_module.JobProcessingError:
                if app_module.time.time() >= deadline:
                    self.fail("background worker did not release its transferred slot")
                app_module.time.sleep(0.01)
                continue
            recovered_slots.release()
            break

    def test_async_acceptance_response_snapshots_status_before_worker_failure(self):
        job = app_module.create_progress_job("format_text")
        snapshot_released = app_module.threading.Event()
        worker_finished = app_module.threading.Event()
        request_thread = app_module.threading.current_thread()

        class InterleavingCondition(app_module.threading.Condition):
            def __exit__(condition, *args):
                result = super().__exit__(*args)
                if app_module.threading.current_thread() is request_thread:
                    snapshot_released.set()
                    if not worker_finished.wait(timeout=5):
                        raise AssertionError("worker could not publish its failure")
                return result

        job["condition"] = InterleavingCondition()

        def fail_after_snapshot():
            try:
                if snapshot_released.wait(timeout=5):
                    app_module.fail_progress_job(job, "worker failed", 500)
            finally:
                worker_finished.set()

        worker = app_module.threading.Thread(target=fail_after_snapshot)
        worker.start()
        try:
            with app_module.app.test_request_context():
                response, status = app_module.build_async_job_http_response(job)
            self.assertEqual(status, 202)
            self.assertEqual(job["status"], "error")
            self.assertTrue(response.get_json()["success"])
            self.assertEqual(response.get_json()["status"], "queued")
            self.assertEqual(response.headers.get("Cache-Control"), "no-store")
            self.assertEqual(
                response.headers.get("Retry-After"),
                str(app_module.JOB_RESULT_RETRY_AFTER_SECONDS),
            )
        finally:
            snapshot_released.set()
            worker.join(timeout=5)
        self.assertFalse(worker.is_alive())

    def test_async_routes_build_response_before_transferring_work_to_worker(self):
        requests = [
            (
                "/api/format_async",
                lambda: {
                    "data": {"file": (BytesIO(self.test_doc_bytes), "正文.docx")},
                    "content_type": "multipart/form-data",
                },
            ),
            (
                "/api/format_text_async",
                lambda: {"json": {"text": "论文标题\n摘要：摘要内容\n关键词：测试\n正文内容"}},
            ),
        ]
        if app_module.is_docxcompose_supported():
            requests.extend(
                [
                    (
                        "/api/format_merge_async",
                        lambda: {
                            "data": {
                                "cover": (BytesIO(self.test_doc_bytes), "封面.docx"),
                                "body": (BytesIO(self.test_doc_bytes), "正文.docx"),
                            },
                            "content_type": "multipart/form-data",
                        },
                    ),
                    (
                        "/api/concat_async",
                        lambda: {
                            "data": {
                                "first": (BytesIO(self.test_doc_bytes), "封面.docx"),
                                "second": (BytesIO(self.test_doc_bytes), "正文.docx"),
                            },
                            "content_type": "multipart/form-data",
                        },
                    ),
                ]
            )

        for endpoint, build_request_kwargs in requests:
            with self.subTest(endpoint=endpoint):
                app_module.PROGRESS_JOBS.clear()
                for path in (*self.upload_dir.glob("*.docx"), *self.output_dir.glob("*.docx")):
                    path.unlink()

                with (
                    patch.object(
                        app_module,
                        "build_async_job_http_response",
                        side_effect=RuntimeError("response encoding failed"),
                    ) as response_builder,
                    patch.object(app_module, "launch_background_job") as launcher,
                ):
                    response = self.client.post(endpoint, **build_request_kwargs())

                self.assertEqual(response.status_code, 500)
                response_builder.assert_called_once()
                launcher.assert_not_called()
                self.assertEqual(app_module.PROGRESS_JOBS, {})
                self.assertEqual(list(self.upload_dir.glob("*.docx")), [])
                self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
                self.assertEqual(app_module.ACTIVE_UPLOAD_RESERVATIONS, {})

