    def test_job_events_reject_excess_streams_and_release_capacity_on_close(self):
        app_module.SSE_CONNECTION_SLOTS = app_module.threading.BoundedSemaphore(1)
        job = app_module.create_progress_job("format_text")
        app_module.emit_job_progress(job, 1, "正在处理文档")

        first_response = self.client.get(job["events_url"], buffered=False)
        try:
            self.assertEqual(first_response.status_code, 200)

            rejected_response = self.client.get(job["events_url"])
            self.assertEqual(rejected_response.status_code, 429)
            self.assertEqual(
                rejected_response.get_json(),
                {"success": False, "error": app_module.SSE_CAPACITY_MESSAGE},
            )
            self.assertEqual(
                rejected_response.headers.get("Retry-After"),
                str(app_module.SSE_RETRY_AFTER_SECONDS),
            )
        finally:
            first_response.close()
            first_response.close()

        recovered_response = self.client.get(job["events_url"], buffered=False)
        try:
            self.assertEqual(recovered_response.status_code, 200)
        finally:
            recovered_response.close()

    def test_graceful_shutdown_closes_existing_sse_and_rejects_new_streams(self):
        app_module.SSE_CONNECTION_SLOTS = app_module.threading.BoundedSemaphore(1)
        job = app_module.create_progress_job("format_text")
        app_module.emit_job_progress(job, 1, "正在处理文档")

        response = self.client.get(job["events_url"], buffered=False)
        self.assertEqual(response.status_code, 200)

        app_module.begin_graceful_shutdown()
        try:
            # 迭代器应在发送已排队事件后立即 EOF，而不是继续 keep-alive。
            b"".join(response.response)
            release_slot = app_module.try_acquire_sse_connection_slot()
            self.assertIsNotNone(release_slot)
            release_slot()

            rejected = self.client.get(job["events_url"])
            self.assertEqual(rejected.status_code, 503)
            self.assertEqual(
                rejected.get_json(),
                {"success": False, "error": app_module.SERVICE_DRAINING_MESSAGE},
            )
            self.assertEqual(
                rejected.headers.get("Retry-After"),
                str(app_module.SSE_RETRY_AFTER_SECONDS),
            )
        finally:
            response.close()

    def test_job_events_recheck_shutdown_after_acquiring_slot(self):
        job = app_module.create_progress_job("format_text")
        original_acquire = app_module.try_acquire_sse_connection_slot
        release_calls = []

        def acquire_then_begin_shutdown():
            release = original_acquire()
            if release is None:
                return None

            def tracked_release():
                release_calls.append(True)
                return release()

            app_module.SHUTDOWN_EVENT.set()
            return tracked_release

        with patch.object(
            app_module,
            "try_acquire_sse_connection_slot",
            side_effect=acquire_then_begin_shutdown,
        ):
            response = self.client.get(job["events_url"])

        self.assertEqual(response.status_code, 503)
        self.assertEqual(
            response.get_json(),
            {"success": False, "error": app_module.SERVICE_DRAINING_MESSAGE},
        )
        self.assertEqual(
            response.headers.get("Retry-After"),
            str(app_module.SSE_RETRY_AFTER_SECONDS),
        )
        self.assertEqual(release_calls, [True])

