    def test_api_health_reports_docxcompose_min_supported_version_from_requirements_with_requirements_include(self):
        root_dir = Path(self.temp_dir.name)
        requirements_path = root_dir / "requirements.in"
        requirements_path.write_text(
            "\n".join(["-r requirements-base.in", "flask==3.1.3"]),
            encoding="utf-8",
        )
        requirements_base_path = root_dir / "requirements-base.in"
        requirements_base_path.write_text(
            "docxcompose==2.2.1",
            encoding="utf-8",
        )
        requirements_texts = {
            str(requirements_path): "\n".join(["-r requirements-base.in", "flask==3.1.3"]),
            str(requirements_base_path): "docxcompose==2.2.1",
        }

        def resolve_mock(self):
            if self.name == "app.py":
                return root_dir / "app.py"
            if self.name == "requirements.in":
                return requirements_path
            if self.name == "requirements-base.in":
                return requirements_base_path
            return self

        def read_text_mock(self, encoding="utf-8"):
            text = requirements_texts.get(str(self))
            if text is not None:
                return text
            raise OSError

        with (
            patch.object(app_module, "__file__", str(root_dir / "app.py")),
            patch.object(app_module.Path, "resolve", resolve_mock),
            patch.object(app_module.Path, "read_text", read_text_mock),
        ):
            version = app_module._read_docxcompose_min_supported_version_from_requirements()
        self.assertEqual(version, "2.2.1")

