    def test_api_health_reports_docxcompose_min_supported_version_from_requirements_with_remote_include(self):
        remote_url = "https://raw.githubusercontent.com/example/repo/main/requirements-base.in"
        root_dir = Path(self.temp_dir.name)
        requirements_path = root_dir / "requirements.in"
        requirements_path.write_text(
            "\n".join([f'-r "{remote_url}"', "flask==3.1.3"]),
            encoding="utf-8",
        )
        requirements_texts = {
            str(requirements_path): "\n".join([f'-r "{remote_url}"', "flask==3.1.3"]),
            remote_url: "docxcompose==2.2.1",
        }

        def resolve_mock(self):
            if self.name == "app.py":
                return root_dir / "app.py"
            if self.name == "requirements.in":
                return requirements_path
            return self

        def read_text_mock(self, encoding="utf-8"):
            text = requirements_texts.get(str(self))
            if text is not None:
                return text
            raise OSError

        def read_remote_requirements_text(url):
            text = requirements_texts.get(url)
            if text is None:
                raise OSError
            return text

        with (
            patch.object(app_module, "__file__", str(root_dir / "app.py")),
            patch.object(app_module.Path, "resolve", resolve_mock),
            patch.object(app_module.Path, "read_text", read_text_mock),
            patch.object(
                app_module,
                "_read_remote_requirements_text",
                side_effect=read_remote_requirements_text,
            ),
        ):
            version = app_module._read_docxcompose_min_supported_version_from_requirements()
        self.assertEqual(version, "2.2.1")

