    def test_remote_requirements_rejects_unsafe_redirect_target(self):
        remote_url = "https://raw.githubusercontent.com/example/repo/main/redirect.in"

        class RedirectedResponse:
            headers = {}

            def __enter__(self):
                return self

            def __exit__(self, *_args):
                return False

            def geturl(self):
                return "file:///etc/passwd"

            def read(self, _size=None):
                return b"docxcompose==2.2.1\n"

        with patch("urllib.request.urlopen", return_value=RedirectedResponse()):
            with self.assertRaises(ValueError):
                app_module._read_remote_requirements_text(remote_url)

