    def test_read_remote_requirements_text_decodes_non_utf8_with_replacement(self):
        remote_url = "https://raw.githubusercontent.com/example/repo/main/requirements.in"

        class MockResponse:
            def read(self):
                return b"docxcompose==2.2.\xff"

            def __enter__(self):
                return self

            def __exit__(self, *exc_info):
                return False

        with patch("urllib.request.urlopen", return_value=MockResponse()):
            content = app_module._read_remote_requirements_text(remote_url)
        self.assertIn("docxcompose==2.2.", content)
        self.assertIn("\ufffd", content)

