    def test_normalize_remote_requirements_source_handles_github_blob(self):
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/blob/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo.git/blob/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo.git/raw/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo.GIT/raw/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://raw.githubusercontent.com/example/repo/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/blob/feature/x/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/feature/x/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://www.github.com/example/repo/blob/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/raw/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "HTTPS://github.com/example/repo/blob/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/tree/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/tree/main/"
            ),
            "https://github.com/example/repo/tree/main/",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/blob/main/requirements.in#L3"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "HTTPS://raw.githubusercontent.com/example/repo/main/requirements.in"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://raw.githubusercontent.com/example/repo/main/requirements.in?raw=1"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://raw.githubusercontent.com/example/repo/main/requirements.in?raw=1#L3"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://raw.githubusercontent.com/example/repo/main/requirements.in#L3"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/blob/main/requirements.in?raw=1"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/raw/main/requirements.in?raw=1#L3"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://github.com/example/repo/raw/main/requirements.in?download=1"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements.in",
        )

    def test_normalize_remote_requirements_source_handles_plain_gist_pages(self):
        expected = "https://gist.githubusercontent.com/example/abc123/raw"
        sources = (
            "https://gist.github.com/example/abc123",
            "https://gist.github.com/example/abc123/",
            "https://gist.github.com/example/abc123?utm_source=test#discussion",
            "https://gist.github.com/example/abc123/raw",
            "https://gist.github.com/example/abc123/raw/",
            "https://gist.githubusercontent.com/example/abc123/raw?download=1#L4",
        )

        for source in sources:
            with self.subTest(source=source):
                self.assertEqual(
                    app_module._normalize_remote_requirements_source(source),
                    expected,
                )

    def test_read_remote_requirements_text_cache_shares_plain_gist_variants(self):
        page_url = "https://gist.github.com/example/abc123?utm_source=test"
        raw_url = "https://gist.githubusercontent.com/example/abc123/raw#L3"

        with patch.dict(app_module._REMOTE_REQUIREMENTS_CACHE, clear=True):
            with patch("urllib.request.urlopen") as mock_urlopen:
                response = mock_urlopen.return_value.__enter__.return_value
                response.headers.get_content_charset.return_value = "utf-8"
                response.read.return_value = b"docxcompose==2.4.5\n"

                first = app_module._read_remote_requirements_text(page_url)
                second = app_module._read_remote_requirements_text(raw_url)

        self.assertEqual(first, "docxcompose==2.4.5\n")
        self.assertEqual(second, first)
        mock_urlopen.assert_called_once_with(
            "https://gist.githubusercontent.com/example/abc123/raw",
            timeout=5,
        )

    def test_read_remote_requirements_text_resolves_gist_file_fragment(self):
        page_url = (
            "https://gist.github.com/example/abc123"
            "#file-requirements-txt-L3-L8"
        )
        raw_url = (
            "https://gist.githubusercontent.com/example/abc123/raw/"
            "deadbeef/requirements.txt"
        )
        metadata = json.dumps(
            {
                "files": {
                    "notes.md": {
                        "filename": "notes.md",
                        "raw_url": (
                            "https://gist.githubusercontent.com/example/abc123/raw/"
                            "cafebabe/notes.md"
                        ),
                    },
                    "requirements.txt": {
                        "filename": "requirements.txt",
                        "raw_url": raw_url,
                    },
                }
            }
        ).encode("utf-8")
        api_response = MagicMock()
        api_response.__enter__.return_value.read.return_value = metadata
        raw_response = MagicMock()
        raw_response.__enter__.return_value.headers.get_content_charset.return_value = (
            "utf-8"
        )
        raw_response.__enter__.return_value.read.return_value = (
            b"docxcompose==2.4.6\n"
        )

        with patch.dict(app_module._GIST_FILE_SOURCE_CACHE, clear=True):
            with patch.dict(app_module._REMOTE_REQUIREMENTS_CACHE, clear=True):
                with patch(
                    "urllib.request.urlopen",
                    side_effect=[api_response, raw_response],
                ) as mock_urlopen:
                    first = app_module._read_remote_requirements_text(page_url)
                    second = app_module._read_remote_requirements_text(page_url)

        self.assertEqual(first, "docxcompose==2.4.6\n")
        self.assertEqual(second, first)
        self.assertEqual(mock_urlopen.call_count, 2)
        api_request = mock_urlopen.call_args_list[0].args[0]
        self.assertEqual(
            api_request.full_url,
            "https://api.github.com/gists/abc123",
        )
        self.assertEqual(
            api_request.get_header("Accept"),
            "application/vnd.github+json",
        )
        self.assertEqual(mock_urlopen.call_args_list[1].args[0], raw_url)

    def test_read_remote_requirements_text_rejects_gist_api_redirect_off_github(self):
        class RedirectedApiResponse:
            headers = {}

            def __enter__(self):
                return self

            def __exit__(self, *_args):
                return False

            def geturl(self):
                return "https://metadata.example.invalid/gists/abc123"

            def read(self, _size=None):
                self.fail("redirected API response must be rejected before reading")

        with patch.dict(app_module._GIST_FILE_SOURCE_CACHE, clear=True):
            with patch("urllib.request.urlopen", return_value=RedirectedApiResponse()) as mock_urlopen:
                with self.assertRaisesRegex(ValueError, "redirect target is unsafe"):
                    app_module._read_remote_requirements_text(
                        "https://gist.github.com/example/abc123#file-requirements-txt"
                    )

        mock_urlopen.assert_called_once()

