    def test_iter_requirement_entries_resolves_local_file_url_include(self):
        with tempfile.TemporaryDirectory() as tmp_dir:
            included_path = Path(tmp_dir) / "requirements extra.txt"
            included_path.write_text(
                "docxcompose==2.4.4\n",
                encoding="utf-8",
            )

            entries = list(
                app_module._iter_requirement_entries(
                    f'-r "{included_path.as_uri()}"\n',
                    include_base_dir=Path(tmp_dir),
                )
            )
            localhost_uri = included_path.as_uri().replace(
                "file:///",
                "file://localhost/",
                1,
            )
            resolved = app_module._resolve_requirements_source(
                localhost_uri,
                Path(tmp_dir),
            )

        self.assertEqual(entries, ["docxcompose==2.4.4"])
        self.assertEqual(resolved, (str(included_path.resolve()), False))

