    def test_read_remote_requirements_text_uses_github_token_only_for_api(self):
        api_url = (
            "https://api.github.com/repos/example/project/contents/requirements.txt"
            "?ref=release%2Fv2"
        )
        token = "github_pat_test_token"

        with patch.dict(os.environ, {"GITHUB_TOKEN": token}):
            with patch.dict(app_module._REMOTE_REQUIREMENTS_CACHE, clear=True):
                with patch("urllib.request.urlopen") as mock_urlopen:
                    response = mock_urlopen.return_value.__enter__.return_value
                    response.headers.get_content_charset.return_value = "utf-8"
                    response.read.return_value = b"docxcompose==2.4.0\n"

                    app_module._read_remote_requirements_text(api_url)
                    api_request = mock_urlopen.call_args.args[0]

                with patch("urllib.request.urlopen") as mock_urlopen:
                    response = mock_urlopen.return_value.__enter__.return_value
                    response.headers.get_content_charset.return_value = "utf-8"
                    response.read.return_value = b"docxcompose==2.4.0\n"

                    ordinary_url = "https://example.com/requirements.txt"
                    app_module._read_remote_requirements_text(ordinary_url)
                    ordinary_request = mock_urlopen.call_args.args[0]

        self.assertEqual(
            api_request.get_header("Authorization"),
            f"Bearer {token}",
        )
        self.assertEqual(ordinary_request, ordinary_url)

