    def test_read_remote_requirements_text_uses_http_charset(self):
        remote_url = (
            "https://raw.githubusercontent.com/example/repo/main/requirements-http-charset.in"
        )
        expected = (
            "--find-links https://example.test/caf\N{LATIN SMALL LETTER E WITH ACUTE}\n"
            "docxcompose==2.2.6"
        )

        class MockHeaders:
            def get_content_charset(self):
                return "cp1252"

        class MockResponse:
            headers = MockHeaders()

            def read(self):
                return expected.encode("cp1252")

            def __enter__(self):
                return self

            def __exit__(self, *exc_info):
                return False

        app_module._REMOTE_REQUIREMENTS_CACHE.clear()
        with patch("urllib.request.urlopen", return_value=MockResponse()):
            self.assertEqual(
                app_module._read_remote_requirements_text(remote_url),
                expected,
            )

    def test_read_remote_requirements_text_decodes_boms_and_declared_encoding(self):
        remote_payloads = {
            "https://raw.githubusercontent.com/example/repo/main/requirements-utf16.in": (
                "docxcompose==2.2.1\n# UTF-16"
            ).encode("utf-16"),
            "https://raw.githubusercontent.com/example/repo/main/requirements-utf32.in": (
                "docxcompose==2.2.2\n# UTF-32"
            ).encode("utf-32"),
            "https://raw.githubusercontent.com/example/repo/main/requirements-cp1252.in": (
                "# remote requirements\n"
                "# coding: cp1252\n"
                "--find-links https://example.test/caf\N{LATIN SMALL LETTER E WITH ACUTE}\n"
                "docxcompose==2.2.3"
            ).encode("cp1252"),
            "https://raw.githubusercontent.com/example/repo/main/requirements-base64.in": (
                b"# coding: base64\ndocxcompose==2.2.4"
            ),
            "https://raw.githubusercontent.com/example/repo/main/requirements-idna.in": (
                b"# coding: idna\ndocxcompose==2.2.5"
            ),
        }

        class MockResponse:
            def __init__(self, payload):
                self.payload = payload

            def read(self):
                return self.payload

            def __enter__(self):
                return self

            def __exit__(self, *exc_info):
                return False

        def fetch_remote(url, timeout):
            self.assertEqual(timeout, 5)
            return MockResponse(remote_payloads[url])

        app_module._REMOTE_REQUIREMENTS_CACHE.clear()
        with patch("urllib.request.urlopen", side_effect=fetch_remote):
            self.assertEqual(
                app_module._read_remote_requirements_text(
                    "https://raw.githubusercontent.com/example/repo/main/requirements-utf16.in"
                ),
                "docxcompose==2.2.1\n# UTF-16",
            )
            self.assertEqual(
                app_module._read_remote_requirements_text(
                    "https://raw.githubusercontent.com/example/repo/main/requirements-utf32.in"
                ),
                "docxcompose==2.2.2\n# UTF-32",
            )
            self.assertEqual(
                app_module._read_remote_requirements_text(
                    "https://raw.githubusercontent.com/example/repo/main/requirements-cp1252.in"
                ),
                "# remote requirements\n"
                "# coding: cp1252\n"
                "--find-links https://example.test/caf\N{LATIN SMALL LETTER E WITH ACUTE}\n"
                "docxcompose==2.2.3",
            )
            self.assertEqual(
                app_module._read_remote_requirements_text(
                    "https://raw.githubusercontent.com/example/repo/main/requirements-base64.in"
                ),
                "# coding: base64\ndocxcompose==2.2.4",
            )
            self.assertEqual(
                app_module._read_remote_requirements_text(
                    "https://raw.githubusercontent.com/example/repo/main/requirements-idna.in"
                ),
                "# coding: idna\ndocxcompose==2.2.5",
            )

    def test_read_remote_requirements_text_cache_normalizes_variants_to_same_key(self):
        remote_url_with_variant = (
            "https://raw.githubusercontent.com/example/repo/main/requirements.in?raw=1#L3"
        )
        remote_url_canonical = "https://raw.githubusercontent.com/example/repo/main/requirements.in"

        class MockResponse:
            def read(self):
                return b"docxcompose==2.2.1"

            def __enter__(self):
                return self

            def __exit__(self, *exc_info):
                return False

        app_module._REMOTE_REQUIREMENTS_CACHE.clear()
        with patch("urllib.request.urlopen", return_value=MockResponse()) as fetcher:
            content_v1 = app_module._read_remote_requirements_text(remote_url_with_variant)
            content_v2 = app_module._read_remote_requirements_text(remote_url_canonical)
        self.assertEqual(content_v1, "docxcompose==2.2.1")
        self.assertEqual(content_v2, "docxcompose==2.2.1")
        fetcher.assert_called_once()

    def test_read_remote_requirements_text_cache_shares_between_github_and_raw_domain(self):
        remote_url_variant = (
            "https://github.com/example/repo/raw/main/requirements.in?raw=1#L3"
        )
        remote_url_canonical = "https://raw.githubusercontent.com/example/repo/main/requirements.in"

        class MockResponse:
            def read(self):
                return b"docxcompose==2.2.1"

            def __enter__(self):
                return self

            def __exit__(self, *exc_info):
                return False

        app_module._REMOTE_REQUIREMENTS_CACHE.clear()
        with patch("urllib.request.urlopen", return_value=MockResponse()) as fetcher:
            content_v1 = app_module._read_remote_requirements_text(remote_url_variant)
            content_v2 = app_module._read_remote_requirements_text(remote_url_canonical)
        self.assertEqual(content_v1, "docxcompose==2.2.1")
        self.assertEqual(content_v2, "docxcompose==2.2.1")
        fetcher.assert_called_once()

        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://gist.github.com/example/1234567890/raw/main/requirements.in"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://gist.github.com/example/1234567890/raw/main/requirements.in?raw=1#L3"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://gist.github.com/example/1234567890?file=requirements.in"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://gist.github.com/example/1234567890?file=subdir%2Frequirements.in"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw/subdir/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://gist.github.com/example/1234567890?file=subdir%2Frequirements%20dev.in"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw/subdir/requirements%20dev.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "HTTPS://gist.githubusercontent.com/example/1234567890/raw/main/requirements.in"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw/main/requirements.in",
        )
        self.assertEqual(
            app_module._normalize_remote_requirements_source(
                "https://gist.github.com/example/1234567890/raw/"
            ),
            "https://gist.githubusercontent.com/example/1234567890/raw",
        )

    def test_iter_requirement_entries_reuses_remote_include_cache(self):
        remote_url = "https://raw.githubusercontent.com/example/repo/main/requirements-base.in"
        response = self._build_mock_remote_response("docxcompose==2.2.1")
        app_module._REMOTE_REQUIREMENTS_CACHE.clear()
        with patch("urllib.request.urlopen", return_value=response) as fetcher:
            entries = list(
                app_module._iter_requirement_entries(
                    "\n".join(
                        [
                            f'-r "{remote_url}"',
                            f'-r "{remote_url}"',
                            "flask==3.1.3",
                        ]
                    )
                )
        )
        self.assertEqual(entries, ["docxcompose==2.2.1", "docxcompose==2.2.1", "flask==3.1.3"])
        self.assertEqual(fetcher.call_count, 1)

