    @staticmethod
    def _build_mock_remote_response(content: str):
        payload = content.encode("utf-8")

        class MockResponse:
            def __init__(self, payload_bytes: bytes):
                self._payload_bytes = payload_bytes

            def read(self):
                return self._payload_bytes

            def __enter__(self):
                return self

            def __exit__(self, *exc_info):
                return False

        return MockResponse(payload)

    def test_iter_requirement_entries_resolves_short_include_quoted_equals_argument(self):
        include_path = Path(self.temp_dir.name) / "requirements spaced.in"
        include_path.write_text("docxcompose==2.2.1", encoding="utf-8")
        requirements_text = "\n".join(
            [
                f'-r=\'{include_path.name}\'',
                "flask==3.1.3",
            ]
        )
        entries = list(
            app_module._iter_requirement_entries(
                requirements_text,
                include_base_dir=Path(self.temp_dir.name),
            )
        )
        self.assertEqual(entries, ["docxcompose==2.2.1", "flask==3.1.3"])

