    def test_is_requirements_control_line(self):
        self.assertTrue(
            app_module._is_requirements_control_line("-r requirements.txt"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--extra-index-url https://pypi.org/simple"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-c constraints.txt"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--no-index"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--index-url=https://pypi.org/simple"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-i https://pypi.org/simple"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-r=requirements-base.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-c=requirements.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-rrequirements-base.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-crequirements.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-f=https://example.com/wheels"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-i=https://pypi.org/simple"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-irequirements.txt"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-e git+https://github.com/example/docxcompose.git#egg=docxcompose"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--editable git+https://github.com/example/docxcompose.git#egg=docxcompose"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--editable=git+https://github.com/example/docxcompose.git#egg=docxcompose"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--requirement requirements-base.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--constraint requirements-base.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--requirement='requirements-base.in'"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line('-r="requirements in quotes.in"'),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-r requirements-base.in"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line('-r "https://raw.githubusercontent.com/example/repo/main/requirements.in"'),
        )
        self.assertTrue(
            app_module._is_requirements_control_line(
                '--requirement="https://raw.githubusercontent.com/example/repo/main/requirements.in"'
            ),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-egit+https://github.com/example/docxcompose.git#egg=docxcompose"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("-egit+https://github.com/example/docxcompose.git#egg=docxcompose  # vcs editable"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--editable=git+https://github.com/example/docxcompose.git#egg=docxcompose  # vcs editable"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--no-binary=:all:"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--no-binary :all:"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--only-binary=:all:"),
        )
        self.assertTrue(
            app_module._is_requirements_control_line("--require-hashes"),
        )
        self.assertFalse(
            app_module._is_requirements_control_line("https://download.example.com/package.whl"),
        )
        self.assertFalse(app_module._is_requirements_control_line("docxcompose==2.2.0"))

