    def test_cors_allowlist_allows_configured_api_origins_only(self):
        if app_module.CORS is None:
            self.skipTest("Flask-Cors is not installed")

        cors_app = app_module.Flask("cors-allowlist-test")

        @cors_app.route("/api/ping")
        def cors_api_ping():
            return {"success": True}

        @cors_app.route("/web/ping")
        def cors_web_ping():
            return "ok"

        mode = app_module.configure_cors(
            cors_app,
            (
                "https://front.example",
                "https://admin.example",
                "https://(trusted.example|evil.example)",
            ),
        )

        client = cors_app.test_client()
        allowed = client.get("/api/ping", headers={"Origin": "https://front.example"})
        preflight = client.options(
            "/api/ping",
            headers={
                "Origin": "https://front.example",
                "Access-Control-Request-Method": "POST",
                "Access-Control-Request-Headers": app_module.CLIENT_JOB_ID_HEADER,
            },
        )
        denied = client.get("/api/ping", headers={"Origin": "https://evil.example"})
        regex_spoofed = client.get(
            "/api/ping",
            headers={"Origin": "https://trusted.example"},
        )
        non_api = client.get("/web/ping", headers={"Origin": "https://front.example"})

        self.assertEqual(mode, "allowlist")
        self.assertEqual(
            allowed.headers.get("Access-Control-Allow-Origin"),
            "https://front.example",
        )
        self.assertEqual(
            allowed.headers.get("Access-Control-Expose-Headers"),
            "Retry-After, X-Request-ID",
        )
        self.assertIn(
            app_module.CLIENT_JOB_ID_HEADER.lower(),
            preflight.headers.get("Access-Control-Allow-Headers", "").lower(),
        )
        self.assertIsNone(denied.headers.get("Access-Control-Allow-Origin"))
        self.assertIsNone(regex_spoofed.headers.get("Access-Control-Allow-Origin"))
        self.assertIsNone(non_api.headers.get("Access-Control-Allow-Origin"))

