    def test_static_assets_include_security_headers_without_no_store(self):
        response = self.client.get("/static/style.css?v=20260907_1")
        try:
            self.assertEqual(response.status_code, 200)
            self.assertEqual(response.headers.get("X-Content-Type-Options"), "nosniff")
            self.assertEqual(response.headers.get("Referrer-Policy"), "strict-origin-when-cross-origin")
            self.assertEqual(response.headers.get("X-Frame-Options"), "DENY")
            self.assertEqual(response.headers.get("Permissions-Policy"), app_module.PERMISSIONS_POLICY)
            self.assertEqual(response.headers.get("Content-Security-Policy"), app_module.CONTENT_SECURITY_POLICY)
            self.assertNotEqual(response.headers.get("Cache-Control"), "no-store")
        finally:
            response.close()

