        self.assertIn('steps.forEach((step) => setStepState(step, "done"));', script)
        for label in ("未开始", "进行中", "已完成"):
            self.assertIn(f'"{label}"', script)
        self.assertIn(".step-status", stylesheet)
        self.assertIn("border: 1px solid currentColor;", stylesheet)

