    def test_frontend_secondary_text_tokens_meet_normal_text_contrast(self):
        stylesheet = Path(app_module.app.static_folder, "style.css").read_text(encoding="utf-8")
        color_variables = dict(
            re.findall(r"--([a-z-]+):\s*(#[0-9a-fA-F]{6});", stylesheet)
        )

        def relative_luminance(hex_color):
            channels = [int(hex_color[index : index + 2], 16) / 255 for index in (1, 3, 5)]
            linear = [
                channel / 12.92
                if channel <= 0.04045
                else ((channel + 0.055) / 1.055) ** 2.4
                for channel in channels
            ]
            return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2]

        def contrast_ratio(first, second):
            lighter, darker = sorted(
                (relative_luminance(first), relative_luminance(second)),
                reverse=True,
            )
            return (lighter + 0.05) / (darker + 0.05)

        background = color_variables["bg-base"]
        for token in ("text-secondary", "text-muted"):
            with self.subTest(token=token):
                self.assertGreaterEqual(
                    contrast_ratio(color_variables[token], background),
                    4.5,
                )
        self.assertGreater(
            relative_luminance(color_variables["text-secondary"]),
            relative_luminance(color_variables["text-muted"]),
        )

