    def test_frontend_pending_poll_preserves_status_and_bounds_transient_failures(self):
        script = Path(app_module.app.static_folder, "script.js").read_text(encoding="utf-8")
        poll = script.split("async function pollAsyncJobResult(", 1)[1].split(
            "\n  function handleProgressEvent", 1
        )[0]
        retry = script.split("async function retryPendingJobResult()", 1)[1].split(
            "\n  // ====== 上传排版", 1
        )[0]
        clear_pending = script.split("function clearPendingJobResult(", 1)[1].split(
            "\n  function restorePendingJobResult", 1
        )[0]

        limit_match = re.search(r"const POLL_TRANSIENT_FAILURE_LIMIT = (\d+);", script)
        attempts_match = re.search(r"const POLL_RESULT_ATTEMPTS = (\d+);", script)
        self.assertIsNotNone(limit_match)
        self.assertIsNotNone(attempts_match)
        self.assertGreaterEqual(int(limit_match.group(1)), 1)
        self.assertLess(int(limit_match.group(1)), int(attempts_match.group(1)))
        self.assertIn("let consecutiveTransientFailures = 0;", poll)
        self.assertIn("consecutiveTransientFailures += 1;", poll)
        self.assertIn("consecutiveTransientFailures >= POLL_TRANSIENT_FAILURE_LIMIT", poll)
        self.assertIn("consecutiveTransientFailures < POLL_TRANSIENT_FAILURE_LIMIT", poll)
        self.assertIn("consecutiveTransientFailures = 0;", poll)
        self.assertIn('res.status === 202 && data.status === "processing"', poll)
        self.assertNotIn('res.status === 202 || data.status === "processing"', poll)
        self.assertIn("throw createResultError(res, data, fallback);", poll)
        self.assertNotIn("if (res.status >= 500 && attempt < attempts - 1)", poll)
        self.assertIn("clearTerminalPendingResult(error, resultUrl);", retry)
        self.assertIn("beginRequest({ allowPending: true })", retry)
        self.assertIn("armJobWaitTimeout(controller);", retry)
        self.assertIn("expectedResultUrl !== pendingResultUrl", clear_pending)
        self.assertIn("window.sessionStorage.removeItem(PENDING_RESULT_STORAGE_KEY)", clear_pending)

