    def test_persistent_deployments_keep_single_worker_and_safe_processing_limit(self):
        root = Path(__file__).resolve().parent.parent
        render_config = (root / "render.yaml").read_text(encoding="utf-8")
        procfile = (root / "Procfile").read_text(encoding="utf-8")
        gunicorn_lifecycle = (root / "gunicorn_config.py").read_text(encoding="utf-8")
        requirements_in = (root / "requirements.in").read_text(encoding="utf-8")
        requirements_lock = (root / "requirements.txt").read_text(encoding="utf-8")

        for config in (render_config, procfile):
            self.assertIn("--config gunicorn_config.py", config)
            self.assertIn("--workers 1", config)
            self.assertIn("--threads 8", config)
            self.assertIn("--graceful-timeout 290", config)

        self.assertIn("maxShutdownDelaySeconds: 300", render_config)
        self.assertIn("autoDeployTrigger: off", render_config)
        self.assertRegex(
            render_config,
            r'- key: REQUEST_HEADER_TIMEOUT_SECONDS\s+value: "10"',
        )
        self.assertRegex(
            render_config,
            r'- key: REQUEST_BODY_TIMEOUT_SECONDS\s+value: "300"',
        )
        self.assertIn("def post_worker_init(worker)", gunicorn_lifecycle)
        self.assertIn("class HeaderDeadlineRequestParser", gunicorn_lifecycle)
        self.assertIn("gunicorn_http.get_parser = get_parser_with_header_deadline", gunicorn_lifecycle)
        self.assertIn("begin_graceful_shutdown()", gunicorn_lifecycle)
        self.assertIn("worker.handle_exit(signum, frame)", gunicorn_lifecycle)

        self.assertIn(
            'buildCommand: "python -m pip install --only-binary=:all: --require-hashes -r requirements.txt"',
            render_config,
        )
        self.assertRegex(render_config, r"- key: PYTHON_VERSION\s+value: 3\.12\.13")
        self.assertRegex(requirements_in, r"(?m)^Flask>=3\.1\.3$")
        self.assertIn("uv pip compile requirements.in --universal --python-version 3.12", requirements_lock)
        self.assertNotRegex(requirements_lock, r"(?m)^[A-Za-z0-9_.-]+>=")
        for package, version in {
            "docxcompose": "2.2.0",
            "flask": "3.1.3",
            "flask-cors": "6.0.5",
            "gunicorn": "26.0.0",
            "python-docx": "1.2.0",
        }.items():
            self.assertRegex(requirements_lock, rf"(?m)^{re.escape(package)}=={re.escape(version)}[ \t]+\\$")

        requirement_blocks = re.split(
            r"(?m)(?=^[a-z0-9][a-z0-9_.-]*==)",
            requirements_lock,
        )[1:]
        self.assertGreaterEqual(len(requirement_blocks), 10)
        for block in requirement_blocks:
            first_line = block.splitlines()[0]
            with self.subTest(locked_requirement=first_line):
                self.assertIn("--hash=sha256:", block)

        locked_versions = {
            canonicalize_name(name): Version(version)
            for name, version in re.findall(
                r"(?m)^([a-z0-9][a-z0-9_.-]*)==([^\s;]+)",
                requirements_lock,
            )
        }
        direct_requirements = [
            Requirement(line)
            for line in requirements_in.splitlines()
            if line.strip() and not line.lstrip().startswith("#")
        ]
        for requirement in direct_requirements:
            name = canonicalize_name(requirement.name)
            with self.subTest(direct_requirement=str(requirement)):
                self.assertIn(name, locked_versions)
                self.assertIn(locked_versions[name], requirement.specifier)

        configured_limit = re.search(
            r"- key: MAX_CONCURRENT_PROCESSING_JOBS\s+value: [\"']?(\d+)[\"']?",
            render_config,
        )
        self.assertIsNotNone(configured_limit)
        self.assertEqual(
            int(configured_limit.group(1)),
            app_module.DEFAULT_CONCURRENT_PROCESSING_JOBS,
        )

        configured_sse_limit = re.search(
            r"- key: MAX_CONCURRENT_SSE_CONNECTIONS\s+value: [\"']?(\d+)[\"']?",
            render_config,
        )
        self.assertIsNotNone(configured_sse_limit)
        self.assertEqual(
            int(configured_sse_limit.group(1)),
            app_module.DEFAULT_CONCURRENT_SSE_CONNECTIONS,
        )
        self.assertLess(
            int(configured_sse_limit.group(1)),
            8,
            "SSE 长连接必须给普通 Gunicorn 请求预留线程",
        )

