    def test_local_static_references_resolve_to_real_assets(self):
        static_dir = Path(app_module.app.static_folder)
        html = (static_dir / "index.html").read_text(encoding="utf-8")
        stylesheet = (static_dir / "style.css").read_text(encoding="utf-8")
        html_refs = set(re.findall(r"""(?:href|src)=["'](/static/[^"']+)["']""", html))
        css_refs = set(re.findall(r"""url\(\s*["']?(/static/[^"')]+)["']?\s*\)""", stylesheet))

        self.assertIn("/static/style.css?v=20260907_1", html_refs)
        self.assertIn("/static/script.js?v=20260912_1", html_refs)
        self.assertIn("/static/logo.png", html_refs)
        self.assertIn("/static/bg.png", css_refs)

        self.assertIn("url('/static/bg.png')", stylesheet)
        for raw_ref in sorted(html_refs | css_refs):
            path_part = raw_ref.split("?", 1)[0].split("#", 1)[0]
            self.assertTrue(path_part.startswith("/static/"), raw_ref)
            asset_path = static_dir / path_part.removeprefix("/static/")
            self.assertTrue(asset_path.is_file(), raw_ref)

            suffix = asset_path.suffix.lower()
            if suffix in {".png", ".jpg", ".jpeg", ".gif", ".webp"}:
                prefix = asset_path.read_bytes()[:2048]
                self.assertNotIn(b"<html", prefix.lower(), raw_ref)
                self.assertNotIn(b"Wikimedia Error", prefix, raw_ref)
                self.assertNotIn(b"Not Found", prefix, raw_ref)

                if suffix == ".png":
                    self.assertTrue(prefix.startswith(b"\x89PNG\r\n\x1a\n"), raw_ref)
                elif suffix in {".jpg", ".jpeg"}:
                    self.assertTrue(prefix.startswith(b"\xff\xd8\xff"), raw_ref)
                elif suffix == ".gif":
                    self.assertTrue(prefix.startswith((b"GIF87a", b"GIF89a")), raw_ref)
                elif suffix == ".webp":
                    self.assertTrue(prefix.startswith(b"RIFF") and prefix[8:12] == b"WEBP", raw_ref)

    def test_static_background_uses_valid_png_asset(self):
        static_dir = Path(app_module.app.static_folder)
        stylesheet = (static_dir / "style.css").read_text(encoding="utf-8")
        background = static_dir / "bg.png"
        legacy_background = static_dir / "bg.jpg"

        self.assertIn("url('/static/bg.png')", stylesheet)
        self.assertTrue(background.read_bytes().startswith(b"\x89PNG\r\n\x1a\n"))
        if legacy_background.exists():
            legacy_prefix = legacy_background.read_bytes()[:2048]
            self.assertNotIn(b"Wikimedia Error", legacy_prefix)
            self.assertNotIn(b"Not Found", legacy_prefix)

    def test_api_internal_error_does_not_leak_exception_details(self):
        original_formatter = app_module.format_academic_paper

        def broken_formatter(input_path, output_path, *_args, **_kwargs):
            Path(output_path).write_bytes(b"partial-output")
            raise RuntimeError(f"secret stack detail at {input_path}")

        app_module.format_academic_paper = broken_formatter

        try:
            with self.assertLogs(app_module.logger, level="ERROR") as logs:
                response = self.client.post(
                    "/api/format",
                    data={"file": (BytesIO(self.test_doc_bytes), "test_input.docx")},
                    content_type="multipart/form-data",
                )
        finally:
            app_module.format_academic_paper = original_formatter

        self.assertEqual(response.status_code, 500)
        self.assertEqual(
            response.get_json(),
            {"success": False, "error": "服务器内部错误，请稍后重试。"},
        )
        self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
        self.assertEqual(response.headers.get("Cache-Control"), "no-store")
        self.assertEqual(response.headers.get("X-Content-Type-Options"), "nosniff")
        log_text = "\n".join(logs.output)
        request_id = response.headers.get("X-Request-ID")
        self.assertRegex(request_id, r"\A[0-9a-f]{32}\Z")
        self.assertIn(f"[request_id={request_id}]", log_text)
        self.assertIn("处理过程中出现异常: RuntimeError: secret stack detail at", log_text)
        self.assertIn("_input.docx", log_text)
        self.assertNotIn(str(self.upload_dir), log_text)
        self.assertNotIn("Traceback", log_text)

