    def test_format_text_tolerates_malformed_formatter_summary(self):
        original_formatter = app_module.format_academic_paper_from_text

        def malformed_formatter(_text, output_path, **_kwargs):
            Path(output_path).write_bytes(self.test_doc_bytes)
            return {
                "stats": {
                    "heading_l1": "-2",
                    "heading_l2": True,
                    "heading_l3": float("inf"),
                    "reference_entry": "3",
                    UnstringifiableKey(): "4",
                    "invalid_key": "5",
                },
                "page_setup": {
                    "page_size": object(),
                    "margins_cm": {
                        "top": "nan",
                        "bottom": object(),
                        "left": "-1",
                        "right": "3.5",
                        "bool_margin": True,
                    },
                    "page_width_cm": True,
                    "header_text": ["bad"],
                    "unexpected": object(),
                },
                "outline": [
                    {"level": "h1", "text": " 有效标题 "},
                    object(),
                    {"level": object(), "text": "缺失层级"},
                    {"level": "h2", "text": ["bad"]},
                    {"level": "h4", "text": "未知层级"},
                    {"level": "h3", "text": "超长标题" * 30},
                    {"level": "h4", "text": " "},
                ],
                "title_text": "超长标题" * 120,
                "table_paragraphs": "7",
                "equation_paragraphs": "not-an-int",
                "formatted_footnotes": "-4",
                "resized_images": "-3",
                "cover_generated": object(),
            }

        app_module.format_academic_paper_from_text = malformed_formatter
        try:
            response = self.client.post(
                "/api/format_text",
                json={"text": "标题\n摘要：内容\n关键词：测试\n正文"},
            )
        finally:
            app_module.format_academic_paper_from_text = original_formatter

        self.assertEqual(response.status_code, 200)
        data = response.get_json()
        self.assertTrue(data["success"])
        self.assertEqual(data["format_summary"]["stats"]["heading_l1"], 0)
        self.assertEqual(data["format_summary"]["stats"]["heading_l2"], 0)
        self.assertEqual(data["format_summary"]["stats"]["heading_l3"], 0)
        self.assertEqual(data["format_summary"]["stats"]["reference_entry"], 3)
        self.assertEqual(data["format_summary"]["stats"]["invalid_key"], 4)
        self.assertEqual(data["format_summary"]["stats"]["invalid_key_2"], 5)
        self.assertEqual(
            data["format_summary"]["page_setup"],
            {"page_size": "", "header_text": "", "margins_cm": {"right": 3.5}},
        )
        self.assertEqual(data["format_summary"]["outline"][0], {"level": "h1", "text": "有效标题"})
        self.assertEqual(data["format_summary"]["outline"][1], {"level": "section", "text": "缺失层级"})
        self.assertEqual(data["format_summary"]["outline"][2], {"level": "section", "text": "未知层级"})
        self.assertEqual(len(data["format_summary"]["outline"]), 4)
        self.assertLessEqual(len(data["format_summary"]["outline"][3]["text"]), 120)
        self.assertLessEqual(
            len(data["format_summary"]["title_text"]),
            app_module.MAX_SUMMARY_TITLE_LENGTH,
        )
        self.assertTrue(data["format_summary"]["title_text"].endswith("…"))
        self.assertEqual(data["format_summary"]["table_paragraphs"], 7)
        self.assertEqual(data["format_summary"]["equation_paragraphs"], 0)
        self.assertEqual(data["format_summary"]["formatted_footnotes"], 0)
        self.assertEqual(data["format_summary"]["resized_images"], 0)
        self.assertIs(data["format_summary"]["cover_generated"], False)
        self.assertEqual(data["preview"]["outline"], data["format_summary"]["outline"])
        self.assertIn("上下 2.54 cm，左右 3.18 cm", data["preview"]["highlights"][0]["description"])
        structure_description = data["preview"]["highlights"][2]["description"]
        self.assertNotIn("-2", structure_description)
        self.assertIn("识别到 3 条参考文献", data["preview"]["highlights"][3]["description"])

