        self.assertEqual(response.get_json()["job_id"], test_job_id)
        self.assertEqual(response.get_json()["status"], "queued")
        self.assertEqual(response.get_json()["events_url"], reusable_job["events_url"])
        launcher.assert_not_called()
        self.assertEqual(app_module.PROGRESS_JOBS[test_job_id]["kind"], "concat")
        self.assertEqual(app_module.PROGRESS_JOBS[test_job_id]["status"], "queued")

