    def test_job_events_clamps_oversized_last_event_id(self):
        job = app_module.create_progress_job("format")
        app_module.emit_job_progress(job, 1, "已接收任务")

        def finish_job():
            app_module.emit_job_progress(job, 2, "继续处理")
            app_module.complete_progress_job(job, {"success": True})

        timer = app_module.threading.Timer(0.01, finish_job)
        timer.start()
        events_response = self.client.get(
            job["events_url"],
            headers={"Last-Event-ID": "999"},
            buffered=True,
        )
        try:
            events_text = events_response.get_data(as_text=True)
        finally:
            timer.join(timeout=1)
            events_response.close()

        self.assertEqual(events_response.status_code, 200)
        self.assertIn("event: progress", events_text)
        self.assertIn("继续处理", events_text)
        self.assertIn("event: complete", events_text)
        self.assertNotIn("已接收任务", events_text)

    def test_job_events_ignores_extremely_long_last_event_id(self):
        job = app_module.create_progress_job("format")
        app_module.emit_job_progress(job, 1, "已接收任务")
        app_module.complete_progress_job(job, {"success": True})

