    def test_async_result_waits_for_atomic_completion_snapshot(self):
        status_written = app_module.threading.Event()
        allow_completion = app_module.threading.Event()
        snapshot_attempted = app_module.threading.Event()
        result_holder = {}

        class TrackingCondition(app_module.threading.Condition):
            def __enter__(self):
                if app_module.threading.current_thread().name == "job-result-reader":
                    snapshot_attempted.set()
                return super().__enter__()

        class PausingJob(dict):
            def __setitem__(self, key, value):
                super().__setitem__(key, value)
                if key == "status" and value == "done":
                    status_written.set()
                    allow_completion.wait(timeout=5)

        original_job = app_module.create_progress_job("format")
        job = PausingJob(original_job)
        job["condition"] = TrackingCondition()
        with app_module.PROGRESS_JOBS_LOCK:
            app_module.PROGRESS_JOBS[job["id"]] = job

        output_path = self.output_dir / f"{job['id']}_output.docx"
        output_path.write_bytes(b"generated output")
        result_payload = {
            "success": True,
            "download_url": f"/api/download/{job['id']}_output.docx",
            "download_name": "测试文档_排版后.docx",
            "stats": {},
            "format_summary": {},
            "preview": {},
        }

        completion_worker = app_module.threading.Thread(
            target=app_module.complete_progress_job,
            args=(job, result_payload),
        )

        def fetch_result():
            with app_module.app.test_client() as client:
                response = client.get(job["result_url"])
                result_holder["status_code"] = response.status_code
                result_holder["payload"] = response.get_json()

        result_worker = app_module.threading.Thread(target=fetch_result, name="job-result-reader")
        try:
            completion_worker.start()
            self.assertTrue(status_written.wait(timeout=5))
            result_worker.start()
            self.assertTrue(snapshot_attempted.wait(timeout=5))
            self.assertTrue(
                result_worker.is_alive(),
                "结果读取应等待同一条件锁，不能观察到仅写入 status 的中间状态",
            )
        finally:
            allow_completion.set()
            completion_worker.join(timeout=5)
            result_worker.join(timeout=5)

        self.assertFalse(completion_worker.is_alive())
        self.assertFalse(result_worker.is_alive())
        self.assertEqual(result_holder["status_code"], 200)
        self.assertTrue(result_holder["payload"]["success"])
        self.assertEqual(
            result_holder["payload"]["download_url"],
            f"/api/download/{job['id']}_output.docx",
        )

