    def test_format_rejects_docx_with_corrupted_xml_crc_before_processing(self):
        corrupted_docx = bytearray(self.test_doc_bytes)
        with zipfile.ZipFile(BytesIO(corrupted_docx)) as archive:
            document_info = archive.getinfo("word/document.xml")
        local_header_offset = document_info.header_offset
        filename_length = int.from_bytes(
            corrupted_docx[local_header_offset + 26 : local_header_offset + 28],
            "little",
        )
        extra_length = int.from_bytes(
            corrupted_docx[local_header_offset + 28 : local_header_offset + 30],
            "little",
        )
        compressed_data_offset = local_header_offset + 30 + filename_length + extra_length
        corrupted_docx[compressed_data_offset + document_info.compress_size // 2] ^= 0xFF

        response = self.client.post(
            "/api/format",
            data={"file": (BytesIO(corrupted_docx), "crc-corrupt.docx")},
            content_type="multipart/form-data",
        )

        self.assertEqual(response.status_code, 400)
        self.assertEqual(
            response.get_json(),
            {
                "success": False,
                "error": app_module.INVALID_DOCX_MESSAGE.format(label="上传的文件"),
            },
        )
        self.assertEqual(list(self.upload_dir.glob("*.docx")), [])
        self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])

    def test_docx_validation_rejects_corrupted_non_xml_member(self):
        content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            b'<Default Extension="bin" ContentType="application/octet-stream"/></Types>',
        )
        fake_docx = BytesIO()
        with zipfile.ZipFile(fake_docx, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("[Content_Types].xml", content_types)
            archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
            archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
            archive.writestr("word/media/blob.bin", b"binary-resource" * 32)

        corrupted_docx = bytearray(fake_docx.getvalue())
        with zipfile.ZipFile(BytesIO(corrupted_docx)) as archive:
            media_info = archive.getinfo("word/media/blob.bin")
        local_header_offset = media_info.header_offset
        filename_length = int.from_bytes(
            corrupted_docx[local_header_offset + 26 : local_header_offset + 28],
            "little",
        )
        extra_length = int.from_bytes(
            corrupted_docx[local_header_offset + 28 : local_header_offset + 30],
            "little",
        )
        compressed_data_offset = local_header_offset + 30 + filename_length + extra_length
        corrupted_docx[compressed_data_offset + media_info.compress_size // 2] ^= 0xFF
        stream = BytesIO(corrupted_docx)

        self.assertFalse(
            app_module.is_valid_docx_upload(
                FileStorage(stream=stream, filename="corrupted-media.docx")
            )
        )
        self.assertEqual(stream.tell(), 0)

