    def test_docx_validation_rejects_dtd_and_entity_declarations(self):
        dtd_content_types = (
            b'<?xml version="1.0"?>'
            b'<!DOCTYPE Types [<!ENTITY harmless "ok">]>'
            b'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            b'<Default Extension="xml" ContentType="application/xml"/>'
            b'<Override PartName="/word/document.xml" '
            b'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
            b'</Types>'
        )
        dtd_document = (
            f'<?xml version="1.0"?><!DOCTYPE w:document '
            f' [<!ENTITY harmless "ok">]><w:document xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
            '<w:body><w:p><w:r><w:t>&harmless;</w:t></w:r></w:p></w:body></w:document>'
        ).encode()
        dtd_document_utf16 = dtd_document.decode().encode("utf-16")
        dtd_styles = (
            b'<?xml version="1.0"?><!DOCTYPE styles [<!ENTITY harmless "ok">]>'
            b'<styles xmlns="http://schemas.openxmlformats.org/wordprocessingml/2006/main"/>'
        )

        cases = (
            (dtd_content_types, MINIMAL_DOCUMENT_XML, None),
            (MINIMAL_CONTENT_TYPES_XML, dtd_document, None),
            (MINIMAL_CONTENT_TYPES_XML, dtd_document_utf16, None),
            (MINIMAL_CONTENT_TYPES_XML, MINIMAL_DOCUMENT_XML, dtd_styles),
        )
        for index, (content_types, document, styles) in enumerate(cases):
            with self.subTest(case=index):
                fake_docx = BytesIO()
                with zipfile.ZipFile(fake_docx, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                    archive.writestr("[Content_Types].xml", content_types)
                    archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                    archive.writestr("word/document.xml", document)
                    if styles is not None:
                        archive.writestr("word/styles.xml", styles)
                fake_docx.seek(0)

                self.assertFalse(
                    app_module.is_valid_docx_upload(
                        FileStorage(stream=fake_docx, filename=f"dtd-{index}.docx")
                    )
                )
                self.assertEqual(fake_docx.tell(), 0)

    def test_content_types_parser_rejects_unknown_children_and_bad_extensions(self):
        unknown_child = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            b"<Unexpected/></Types>",
        )
        slash_extension = MINIMAL_CONTENT_TYPES_XML.replace(
            b'Extension="xml"',
            b'Extension="word/xml"',
            1,
        )
        dotted_extension = MINIMAL_CONTENT_TYPES_XML.replace(
            b'Extension="xml"',
            b'Extension=".xml"',
            1,
        )
        nested_default = MINIMAL_CONTENT_TYPES_XML.replace(
            b'ContentType="application/xml"/>',
            b'ContentType="application/xml"><Unexpected/></Default>',
            1,
        )
        text_override = MINIMAL_CONTENT_TYPES_XML.replace(
            b'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>',
            b'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">text</Override>',
            1,
        )
        root_text = MINIMAL_CONTENT_TYPES_XML.replace(
            b">\n  <Default",
            b">not-whitespace<Default",
            1,
        )
        spaced_extension = MINIMAL_CONTENT_TYPES_XML.replace(
            b'Extension="xml"',
            b'Extension=" xml"',
            1,
        )
        spaced_part_name = MINIMAL_CONTENT_TYPES_XML.replace(
            b'PartName="/word/document.xml"',
            b'PartName="/word/document.xml "',
            1,
        )

        for index, content_types in enumerate(
            (
                unknown_child,
                slash_extension,
                dotted_extension,
                nested_default,
                text_override,
                root_text,
                spaced_extension,
                spaced_part_name,
            )
        ):
            with self.subTest(case=index):
                payload = BytesIO()
                with zipfile.ZipFile(payload, "w") as archive:
                    archive.writestr("[Content_Types].xml", content_types)
                    archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                payload.seek(0)
                with zipfile.ZipFile(payload) as archive:
                    self.assertIsNone(app_module.parse_docx_content_types(archive))

        self.assertEqual(
            app_module.docx_member_content_type(
                "word.v1/media/extensionless",
                {"v1/media/extensionless": "application/xml"},
                {},
            ),
            "",
        )

