    def test_docx_validation_rejects_unicode_case_equivalent_override_duplicates(self):
        styles_content_type = (
            "application/vnd.openxmlformats-officedocument."
            "wordprocessingml.styles+xml"
        )
        content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            (
                f'<Override PartName="/word/ẞtyles.xml" '
                f'ContentType="{styles_content_type}"/>'
                '<Override PartName="/word/ßtyles.xml" '
                'ContentType="application/xml"/></Types>'
            ).encode(),
        )
        document_relationships = (
            f'<Relationships xmlns="{app_module.PACKAGE_RELATIONSHIPS_NAMESPACE}">'
            '<Relationship Id="rIdStyles" '
            f'Type="{app_module.OFFICE_DOCUMENT_RELATIONSHIPS_NAMESPACE}/styles" '
            'Target="ẞtyles.xml"/></Relationships>'
        ).encode()
        styles_xml = (
            f'<w:styles xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}"/>'
        ).encode()

        payload = BytesIO()
        with zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("[Content_Types].xml", content_types)
            archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
            archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
            archive.writestr("word/_rels/document.xml.rels", document_relationships)
            archive.writestr("word/ẞtyles.xml", styles_xml)
        archive_bytes = payload.getvalue()

        # python-docx 会将两个 Override 归一到同一键并采用后者，
        # 从而把 styles 降级成不具备 .styles 属性的通用 Part。
        document = Document(BytesIO(archive_bytes))
        with self.assertRaises(AttributeError):
            len(document.styles)

        upload_stream = BytesIO(archive_bytes)
        self.assertFalse(
            app_module.is_valid_docx_upload(
                FileStorage(
                    stream=upload_stream,
                    filename="unicode-override-duplicate.docx",
                )
            )
        )
        self.assertEqual(upload_stream.tell(), 0)

        with tempfile.TemporaryDirectory() as temp_dir:
            output_path = Path(temp_dir) / "unicode-override-duplicate.docx"
            output_path.write_bytes(archive_bytes)
            self.assertFalse(app_module.is_valid_generated_docx(output_path))

    def test_docx_validation_rejects_ambiguous_or_percent_encoded_override_aliases(self):
        duplicate_override = (
            b'<Override PartName="/WORD/DOCUMENT.XML" ContentType="application/xml"/>'
        )
        cases = (
            lambda content_types: content_types.replace(
                b"/word/document.xml",
                b"/word/%64ocument.xml",
                1,
            ),
            lambda content_types: content_types.replace(
                b"</Types>",
                duplicate_override + b"</Types>",
                1,
            ),
        )

        with tempfile.TemporaryDirectory() as temp_dir:
            for index, mutate_content_types in enumerate(cases):
                with self.subTest(case=index):
                    payload = BytesIO()
                    with (
                        zipfile.ZipFile(BytesIO(self.test_doc_bytes)) as source,
                        zipfile.ZipFile(
                            payload,
                            "w",
                            compression=zipfile.ZIP_DEFLATED,
                        ) as target,
                    ):
                        for member in source.infolist():
                            member_payload = source.read(member)
                            if member.filename == "[Content_Types].xml":
                                member_payload = mutate_content_types(member_payload)
                            target.writestr(member, member_payload)

                    archive_bytes = payload.getvalue()
                    upload_stream = BytesIO(archive_bytes)
                    self.assertFalse(
                        app_module.is_valid_docx_upload(
                            FileStorage(
                                stream=upload_stream,
                                filename=f"override-part-alias-{index}.docx",
                            )
                        )
                    )
                    self.assertEqual(upload_stream.tell(), 0)
                    output_path = Path(temp_dir) / f"override-part-alias-{index}.docx"
                    output_path.write_bytes(archive_bytes)
                    self.assertFalse(app_module.is_valid_generated_docx(output_path))

