    def test_docx_validation_accepts_case_aliases_for_all_generic_related_parts(self):
        word_namespace = app_module.WORDPROCESSINGML_NAMESPACE
        office_relationships = app_module.OFFICE_DOCUMENT_RELATIONSHIPS_NAMESPACE
        cases = (
            (
                "footnotes",
                "document",
                "word/footnotes.xml",
                f"{office_relationships}/footnotes",
                "application/vnd.openxmlformats-officedocument."
                "wordprocessingml.footnotes+xml",
                (
                    f'<w:footnotes xmlns:w="{word_namespace}">'
                    '<w:footnote w:id="2"><w:p><w:r><w:t>Footnote</w:t></w:r>'
                    "</w:p></w:footnote></w:footnotes>"
                ).encode(),
                1,
            ),
            (
                "endnotes",
                "document",
                "word/endnotes.xml",
                f"{office_relationships}/endnotes",
                "application/vnd.openxmlformats-officedocument."
                "wordprocessingml.endnotes+xml",
                f'<w:endnotes xmlns:w="{word_namespace}"/>'.encode(),
                0,
            ),
            (
                "glossary",
                "document",
                "word/glossary/document.xml",
                f"{office_relationships}/glossaryDocument",
                "application/vnd.openxmlformats-officedocument."
                "wordprocessingml.document.glossary+xml",
                f'<w:glossaryDocument xmlns:w="{word_namespace}"/>'.encode(),
                0,
            ),
            (
                "extended-properties",
                "existing-root",
                "docProps/app.xml",
                f"{office_relationships}/extended-properties",
                "application/vnd.openxmlformats-officedocument."
                "extended-properties+xml",
                None,
                0,
            ),
            (
                "custom-properties",
                "root",
                "docProps/custom.xml",
                f"{office_relationships}/custom-properties",
                "application/vnd.openxmlformats-officedocument."
                "custom-properties+xml",
                (
                    f'<Properties xmlns="{app_module.CUSTOM_PROPERTIES_NAMESPACE}"/>'
                ).encode(),
                0,
            ),
        )

        with tempfile.TemporaryDirectory() as temp_dir:
            temp_path = Path(temp_dir)
            for (
                label,
                scope,
                member_name,
                relationship_type,
                content_type,
                part_payload,
                expected_footnotes,
            ) in cases:
                with self.subTest(part=label):
                    alias = content_type.upper()
                    payload = BytesIO()
                    with (
                        zipfile.ZipFile(BytesIO(self.test_doc_bytes)) as source,
                        zipfile.ZipFile(
                            payload,
                            "w",
                            compression=zipfile.ZIP_DEFLATED,
                        ) as target,
                    ):
                        for member in source.infolist():
                            member_payload = source.read(member)
                            if member.filename == "[Content_Types].xml":
                                if scope == "existing-root":
                                    self.assertIn(content_type.encode(), member_payload)
                                    member_payload = member_payload.replace(
                                        content_type.encode(),
                                        alias.encode(),
                                        1,
                                    )
                                else:
                                    member_payload = member_payload.replace(
                                        b"</Types>",
                                        (
                                            f'<Override PartName="/{member_name}" '
                                            f'ContentType="{alias}"/></Types>'
                                        ).encode(),
                                        1,
                                    )

                            relationship_member = (
                                "word/_rels/document.xml.rels"
                                if scope == "document"
                                else "_rels/.rels"
                            )
                            if (
                                scope != "existing-root"
                                and member.filename == relationship_member
                            ):
                                target_name = (
                                    member_name.removeprefix("word/")
                                    if scope == "document"
                                    else member_name
                                )
                                member_payload = member_payload.replace(
                                    b"</Relationships>",
                                    (
                                        '<Relationship Id="rIdGenericCaseAlias" '
                                        f'Type="{relationship_type}" '
                                        f'Target="{target_name}"/></Relationships>'
                                    ).encode(),
                                    1,
                                )
                            target.writestr(member, member_payload)

                        if part_payload is not None:
                            target.writestr(member_name, part_payload)

                    archive_bytes = payload.getvalue()
                    document = Document(BytesIO(archive_bytes))
                    relationship_source = (
                        document.part if scope == "document" else document.part.package
                    )
                    relationship = next(
                        rel
                        for rel in relationship_source.rels.values()
                        if rel.reltype == relationship_type
                    )
                    self.assertIs(type(relationship.target_part), Part)
                    self.assertEqual(relationship.target_part.content_type, alias)

                    upload_stream = BytesIO(archive_bytes)
                    self.assertTrue(
                        app_module.is_valid_docx_upload(
                            FileStorage(
                                stream=upload_stream,
                                filename=f"generic-case-{label}.docx",
                            )
                        )
                    )
                    self.assertEqual(upload_stream.tell(), 0)

                    input_path = temp_path / f"generic-case-{label}.docx"
                    output_path = temp_path / f"generic-case-{label}-output.docx"
                    input_path.write_bytes(archive_bytes)
                    self.assertTrue(app_module.is_valid_generated_docx(input_path))
                    summary = format_paper_module.format_academic_paper(
                        input_path,
                        output_path,
                    )
                    self.assertEqual(
                        summary["formatted_footnotes"],
                        expected_footnotes,
                    )
                    self.assertTrue(app_module.is_valid_generated_docx(output_path))
                    self.assertGreater(len(Document(output_path).paragraphs), 0)
                    with zipfile.ZipFile(output_path) as output_archive:
                        self.assertIn(member_name, output_archive.namelist())
                        self.assertIn(
                            alias.encode(),
                            output_archive.read("[Content_Types].xml"),
                        )

