    def test_docx_validation_requires_content_type_for_every_part(self):
        declared_content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            b'<Default Extension="png" ContentType="image/png"/></Types>',
        )
        cases = (
            (MINIMAL_CONTENT_TYPES_XML, False),
            (declared_content_types, True),
        )
        with tempfile.TemporaryDirectory() as temp_dir:
            for index, (content_types, expected) in enumerate(cases):
                with self.subTest(declared=expected):
                    payload = BytesIO()
                    with zipfile.ZipFile(
                        payload,
                        "w",
                        compression=zipfile.ZIP_DEFLATED,
                    ) as archive:
                        archive.writestr("[Content_Types].xml", content_types)
                        archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                        archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                        archive.writestr("word/media/image1.png", b"not-a-real-image")
                    archive_bytes = payload.getvalue()

                    upload_stream = BytesIO(archive_bytes)
                    self.assertEqual(
                        app_module.is_valid_docx_upload(
                            FileStorage(
                                stream=upload_stream,
                                filename=f"content-types-{index}.docx",
                            )
                        ),
                        expected,
                    )
                    output_path = Path(temp_dir) / f"content-types-{index}.docx"
                    output_path.write_bytes(archive_bytes)
                    self.assertEqual(
                        app_module.is_valid_generated_docx(output_path),
                        expected,
                    )

