    def test_docx_validation_accepts_relocated_main_document_part(self):
        source = BytesIO(self.test_doc_bytes)
        relocated = BytesIO()
        with (
            zipfile.ZipFile(source) as input_archive,
            zipfile.ZipFile(relocated, "w", compression=zipfile.ZIP_DEFLATED) as output_archive,
        ):
            for member in input_archive.infolist():
                member_name = member.filename
                payload = input_archive.read(member)
                if member_name == "[Content_Types].xml":
                    payload = payload.replace(b"/word/document.xml", b"/word/main.xml")
                elif member_name == "_rels/.rels":
                    payload = payload.replace(b"word/document.xml", b"word/main.xml")
                elif member_name == "word/document.xml":
                    member_name = "word/main.xml"
                elif member_name == "word/_rels/document.xml.rels":
                    member_name = "word/_rels/main.xml.rels"
                output_archive.writestr(member_name, payload)

        archive_bytes = relocated.getvalue()
        self.assertGreater(len(Document(BytesIO(archive_bytes)).paragraphs), 0)

        upload_stream = BytesIO(archive_bytes)
        self.assertTrue(
            app_module.is_valid_docx_upload(
                FileStorage(stream=upload_stream, filename="relocated-main.docx")
            )
        )
        with tempfile.TemporaryDirectory() as temp_dir:
            output_path = Path(temp_dir) / "relocated-main.docx"
            output_path.write_bytes(archive_bytes)
            self.assertTrue(app_module.is_valid_generated_docx(output_path))

            root_content_types = MINIMAL_CONTENT_TYPES_XML.replace(
                b"/word/document.xml",
                b"/main.xml",
            )
            root_relationships = MINIMAL_ROOT_RELS_XML.replace(
                b"word/document.xml",
                b"main.xml",
            )
            root_main_path = Path(temp_dir) / "root-main.docx"
            with zipfile.ZipFile(
                root_main_path,
                "w",
                compression=zipfile.ZIP_DEFLATED,
            ) as archive:
                archive.writestr("[Content_Types].xml", root_content_types)
                archive.writestr("_rels/.rels", root_relationships)
                archive.writestr("main.xml", MINIMAL_DOCUMENT_XML)
            root_main_bytes = root_main_path.read_bytes()

            self.assertEqual(len(Document(BytesIO(root_main_bytes)).paragraphs), 1)
            self.assertTrue(
                app_module.is_valid_docx_upload(
                    FileStorage(
                        stream=BytesIO(root_main_bytes),
                        filename="root-main.docx",
                    )
                )
            )
            self.assertTrue(app_module.is_valid_generated_docx(root_main_path))

        self.assertEqual(
            app_module._relationship_source_part_name("_rels/main.xml.rels"),
            "main.xml",
        )

    def test_docx_validation_rejects_ascii_case_equivalent_part_names(self):
        payload = BytesIO()
        with (
            zipfile.ZipFile(BytesIO(self.test_doc_bytes)) as source,
            zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as target,
        ):
            document_xml = source.read("word/document.xml")
            for member in source.infolist():
                target.writestr(member.filename, source.read(member))
            target.writestr("word/Document.xml", document_xml)
        archive_bytes = payload.getvalue()

        upload_stream = BytesIO(archive_bytes)
        self.assertFalse(
            app_module.is_valid_docx_upload(
                FileStorage(stream=upload_stream, filename="case-collision.docx")
            )
        )
        with tempfile.TemporaryDirectory() as temp_dir:
            output_path = Path(temp_dir) / "case-collision.docx"
            output_path.write_bytes(archive_bytes)
            self.assertFalse(app_module.is_valid_generated_docx(output_path))

        self.assertNotEqual(
            app_module.canonical_docx_part_name("word/ß.xml"),
            app_module.canonical_docx_part_name("word/SS.xml"),
        )
        self.assertEqual(
            app_module.canonical_docx_part_name("word/ß.xml"),
            app_module.canonical_docx_part_name("word/ẞ.xml"),
        )

    def test_docx_validation_rejects_nested_relationship_content(self):
        namespace = app_module.PACKAGE_RELATIONSHIPS_NAMESPACE
        office_type = (
            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"
        )
        root_with_nested_child = (
            f'<Relationships xmlns="{namespace}">'
            f'<Relationship Id="rId1" Type="{office_type}" Target="word/document.xml">'
            "<Bogus/></Relationship></Relationships>"
        ).encode()
        root_with_text_content = (
            f'<Relationships xmlns="{namespace}">'
            f'<Relationship Id="rId1" Type="{office_type}" '
            'Target="word/document.xml">not-empty</Relationship></Relationships>'
        ).encode()
        root_with_leading_text = (
            f'<Relationships xmlns="{namespace}">not-empty'
            f'<Relationship Id="rId1" Type="{office_type}" '
            'Target="word/document.xml"/></Relationships>'
        ).encode()
        root_with_relationship_tail = (
            f'<Relationships xmlns="{namespace}">'
            f'<Relationship Id="rId1" Type="{office_type}" '
            'Target="word/document.xml"/>not-empty</Relationships>'
        ).encode()
        part_with_nested_child = (
            f'<Relationships xmlns="{namespace}">'
            '<Relationship Id="rIdLink" Type="https://example.test/relationships/link" '
            'Target="https://example.test" TargetMode="External">'
            "<Bogus/></Relationship></Relationships>"
        ).encode()

        cases = (
            (root_with_nested_child, None),
            (root_with_text_content, None),
            (root_with_leading_text, None),
            (root_with_relationship_tail, None),
            (MINIMAL_ROOT_RELS_XML, part_with_nested_child),
        )
        with tempfile.TemporaryDirectory() as temp_dir:
            for index, (root_relationships, document_relationships) in enumerate(cases):
                with self.subTest(case=index):
                    payload = BytesIO()
                    with zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                        archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                        archive.writestr("_rels/.rels", root_relationships)
                        archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                        if document_relationships is not None:
                            archive.writestr(
                                "word/_rels/document.xml.rels",
                                document_relationships,
                            )
                    archive_bytes = payload.getvalue()
                    upload_stream = BytesIO(archive_bytes)
                    self.assertFalse(
                        app_module.is_valid_docx_upload(
                            FileStorage(
                                stream=upload_stream,
                                filename=f"nested-relationship-{index}.docx",
                            )
                        )
                    )
                    output_path = Path(temp_dir) / f"nested-relationship-{index}.docx"
                    output_path.write_bytes(archive_bytes)
                    self.assertFalse(app_module.is_valid_generated_docx(output_path))

    def test_docx_validation_rejects_root_property_relationship_type_mismatch(self):
        property_relationship_types = (
            "http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties",
            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties",
            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties",
        )
        content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            (
                b'<Override PartName="/word/styles.xml" ContentType="application/vnd.'
                b'openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>'
            ),
        )
        styles_xml = (
            f'<w:styles xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}"/>'
        ).encode()

        with tempfile.TemporaryDirectory() as temp_dir:
            for index, relationship_type in enumerate(property_relationship_types):
                with self.subTest(relationship_type=relationship_type):
                    root_relationships = MINIMAL_ROOT_RELS_XML.replace(
                        b"</Relationships>",
                        (
                            f'<Relationship Id="rIdProperty" Type="{relationship_type}" '
                            'Target="word/styles.xml"/></Relationships>'
                        ).encode(),
                    )
                    payload = BytesIO()
                    with zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                        archive.writestr("[Content_Types].xml", content_types)
                        archive.writestr("_rels/.rels", root_relationships)
                        archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                        archive.writestr("word/styles.xml", styles_xml)
                    archive_bytes = payload.getvalue()

                    upload_stream = BytesIO(archive_bytes)
                    self.assertFalse(
                        app_module.is_valid_docx_upload(
                            FileStorage(
                                stream=upload_stream,
                                filename=f"root-property-mismatch-{index}.docx",
                            )
                        )
                    )
                    output_path = Path(temp_dir) / f"root-property-mismatch-{index}.docx"
                    output_path.write_bytes(archive_bytes)
                    self.assertFalse(app_module.is_valid_generated_docx(output_path))

    def test_generated_docx_validation_checks_all_xml_parts_and_declared_roots(self):
        custom_header_name = "word/custom-running-header.xml"
        content_types = MINIMAL_CONTENT_TYPES_XML.replace(
            b"</Types>",
            (
                b'<Override PartName="/' + custom_header_name.encode()
                + b'" ContentType="application/vnd.openxmlformats-officedocument.'
                b'wordprocessingml.header+xml"/></Types>'
            ),
        )
        valid_header = (
            f'<w:hdr xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}"><w:p/></w:hdr>'
        ).encode()
        invalid_header = (
            f'<w:ftr xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}"><w:p/></w:ftr>'
        ).encode()
        custom_dtd = b'<!DOCTYPE root [<!ENTITY value "expanded">]><root>&value;</root>'
        deep_custom_xml = (
            b"<root>"
            + b"<item>" * (app_module.MAX_DOCX_XML_DEPTH + 1)
            + b"</item>" * (app_module.MAX_DOCX_XML_DEPTH + 1)
            + b"</root>"
        )

        cases = {
            "custom-dtd": (MINIMAL_CONTENT_TYPES_XML, {"customXml/item1.xml": custom_dtd}, False),
            "custom-depth": (
                MINIMAL_CONTENT_TYPES_XML,
                {"customXml/item1.xml": deep_custom_xml},
                False,
            ),
            "custom-malformed": (
                MINIMAL_CONTENT_TYPES_XML,
                {"customXml/item1.xml": b"<root>"},
                False,
            ),
            "renamed-header-wrong-root": (
                content_types,
                {custom_header_name: invalid_header},
                False,
            ),
            "renamed-header-valid-root": (
                content_types,
                {custom_header_name: valid_header},
                True,
            ),
        }

        with tempfile.TemporaryDirectory() as temp_dir:
            for label, (declared_types, extra_members, expected) in cases.items():
                with self.subTest(case=label):
                    output_path = Path(temp_dir) / f"{label}.docx"
                    with zipfile.ZipFile(
                        output_path,
                        "w",
                        compression=zipfile.ZIP_DEFLATED,
                    ) as archive:
                        archive.writestr("[Content_Types].xml", declared_types)
                        archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                        archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                        for member_name, payload in extra_members.items():
                            archive.writestr(member_name, payload)

                    self.assertEqual(
                        app_module.is_valid_generated_docx(output_path),
                        expected,
                    )

