    def test_docx_validation_and_formatter_support_relocated_footnotes(self):
        relocated_name = "word/notes/footnotes2.xml"
        footnote_content_type = (
            "application/vnd.openxmlformats-officedocument."
            "wordprocessingml.footnotes+xml"
        )
        footnote_relationship_type = (
            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/footnotes"
        )
        footnotes_xml = (
            f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            f'<w:footnotes xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
            '<w:footnote w:id="2"><w:p><w:r><w:t>Relocated footnote</w:t></w:r>'
            "</w:p></w:footnote></w:footnotes>"
        ).encode()

        payload = BytesIO()
        with (
            zipfile.ZipFile(BytesIO(self.test_doc_bytes)) as source,
            zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as target,
        ):
            for member in source.infolist():
                member_payload = source.read(member)
                if member.filename == "[Content_Types].xml":
                    member_payload = member_payload.replace(
                        b"</Types>",
                        (
                            f'<Override PartName="/{relocated_name}" '
                            f'ContentType="{footnote_content_type}"/></Types>'
                        ).encode(),
                        1,
                    )
                elif member.filename == "word/_rels/document.xml.rels":
                    member_payload = member_payload.replace(
                        b"</Relationships>",
                        (
                            '<Relationship Id="rIdRelocatedFootnotes" '
                            f'Type="{footnote_relationship_type}" '
                            'Target="notes/footnotes2.xml"/></Relationships>'
                        ).encode(),
                        1,
                    )
                target.writestr(member, member_payload)
            target.writestr(relocated_name, footnotes_xml)

        archive_bytes = payload.getvalue()
        upload_stream = BytesIO(archive_bytes)
        self.assertTrue(
            app_module.is_valid_docx_upload(
                FileStorage(stream=upload_stream, filename="relocated-footnotes.docx")
            )
        )
        self.assertEqual(upload_stream.tell(), 0)

        with tempfile.TemporaryDirectory() as temp_dir:
            temp_path = Path(temp_dir)
            input_path = temp_path / "relocated-footnotes.docx"
            output_path = temp_path / "relocated-footnotes-output.docx"
            input_path.write_bytes(archive_bytes)

            self.assertTrue(app_module.is_valid_generated_docx(input_path))
            result = format_paper_module.format_academic_paper(input_path, output_path)

            self.assertIsInstance(result, dict)
            self.assertEqual(result["formatted_footnotes"], 1)
            self.assertTrue(app_module.is_valid_generated_docx(output_path))
            self.assertGreater(len(Document(str(output_path)).paragraphs), 0)
            with zipfile.ZipFile(output_path) as archive:
                self.assertIsNone(archive.testzip())
                self.assertIn(relocated_name, archive.namelist())
                self.assertNotIn("word/footnotes.xml", archive.namelist())
                formatted_footnotes = archive.read(relocated_name)
            self.assertIn(b"w:rFonts", formatted_footnotes)
            self.assertIn(b'w:val="20"', formatted_footnotes)

