    def test_generated_docx_validation_limits_xml_member_and_total_bytes(self):
        original_member_limit = app_module.MAX_GENERATED_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES
        original_total_limit = app_module.MAX_GENERATED_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES
        try:
            with tempfile.TemporaryDirectory() as temp_dir:
                temp_path = Path(temp_dir)
                largest_required_member = max(
                    len(MINIMAL_CONTENT_TYPES_XML),
                    len(MINIMAL_ROOT_RELS_XML),
                    len(MINIMAL_DOCUMENT_XML),
                )
                app_module.MAX_GENERATED_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES = (
                    largest_required_member + 32
                )
                app_module.MAX_GENERATED_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES = 16 * 1024
                oversized_member_path = temp_path / "oversized-xml-member.docx"
                with zipfile.ZipFile(
                    oversized_member_path,
                    "w",
                    compression=zipfile.ZIP_DEFLATED,
                ) as archive:
                    archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                    archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                    archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                    archive.writestr(
                        "customXml/item1.xml",
                        b"<root>" + b"x" * (largest_required_member + 64) + b"</root>",
                    )
                self.assertFalse(app_module.is_valid_generated_docx(oversized_member_path))

                app_module.MAX_GENERATED_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES = 16 * 1024
                app_module.MAX_GENERATED_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES = (
                    len(MINIMAL_CONTENT_TYPES_XML)
                    + len(MINIMAL_ROOT_RELS_XML)
                    + len(MINIMAL_DOCUMENT_XML)
                    + 16
                )
                oversized_total_path = temp_path / "oversized-xml-total.docx"
                with zipfile.ZipFile(
                    oversized_total_path,
                    "w",
                    compression=zipfile.ZIP_DEFLATED,
                ) as archive:
                    archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                    archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                    archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                    archive.writestr("customXml/item1.xml", b"<root>extra payload</root>")
                self.assertFalse(app_module.is_valid_generated_docx(oversized_total_path))
        finally:
            app_module.MAX_GENERATED_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES = original_member_limit
            app_module.MAX_GENERATED_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES = original_total_limit

    def test_docx_validation_rejects_excessive_xml_depth_and_element_count(self):
        original_depth = app_module.MAX_DOCX_XML_DEPTH
        original_elements = app_module.MAX_DOCX_XML_ELEMENTS
        original_total_elements = app_module.MAX_DOCX_TOTAL_XML_ELEMENTS
        try:
            app_module.MAX_DOCX_XML_DEPTH = 4
            deep_document = (
                f'<w:document xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
                '<w:body><w:p><w:r><w:t>too deep</w:t></w:r></w:p></w:body></w:document>'
            ).encode()
            deep_docx = BytesIO()
            with zipfile.ZipFile(deep_docx, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                archive.writestr("word/document.xml", deep_document)
            deep_docx.seek(0)
            self.assertFalse(
                app_module.is_valid_docx_upload(
                    FileStorage(stream=deep_docx, filename="deep.xml.docx")
                )
            )

            app_module.MAX_DOCX_XML_DEPTH = original_depth
            app_module.MAX_DOCX_XML_ELEMENTS = 3
            many_elements_styles = (
                f'<w:styles xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
                "<w:style/><w:style/><w:style/></w:styles>"
            ).encode()
            many_elements_docx = BytesIO()
            with zipfile.ZipFile(many_elements_docx, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                archive.writestr("word/styles.xml", many_elements_styles)
            many_elements_docx.seek(0)
            self.assertFalse(
                app_module.is_valid_docx_upload(
                    FileStorage(stream=many_elements_docx, filename="many-elements.docx")
                )
            )

            app_module.MAX_DOCX_XML_ELEMENTS = original_elements
            # 根关系有 2 个元素，最小主文档有 3 个；留出 1 个后，
            # 额外的两元素 XML 部件才应触发整包预算。
            app_module.MAX_DOCX_TOTAL_XML_ELEMENTS = 6
            two_element_styles = (
                f'<w:styles xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
                "<w:style/></w:styles>"
            ).encode()
            total_elements_docx = BytesIO()
            with zipfile.ZipFile(total_elements_docx, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                archive.writestr("word/styles.xml", two_element_styles)
            total_elements_docx.seek(0)
            self.assertFalse(
                app_module.is_valid_docx_upload(
                    FileStorage(stream=total_elements_docx, filename="total-elements.docx")
                )
            )
        finally:
            app_module.MAX_DOCX_XML_DEPTH = original_depth
            app_module.MAX_DOCX_XML_ELEMENTS = original_elements
            app_module.MAX_DOCX_TOTAL_XML_ELEMENTS = original_total_elements

    def test_docx_validation_rejects_unsafe_member_names_and_symlink_entries(self):
        unsafe_names = (
            "../outside.xml",
            "/absolute.xml",
            "word\\escape.xml",
            "word/%2e%2e/escape.xml",
            "word/%00evil.xml",
            "word%2Fdocument.xml",
        )
        for index, unsafe_name in enumerate(unsafe_names):
            with self.subTest(member_name=unsafe_name):
                fake_docx = BytesIO()
                with zipfile.ZipFile(fake_docx, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                    archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                    archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                    archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                    archive.writestr(unsafe_name, b"<extra/>")
                fake_docx.seek(0)

                self.assertFalse(
                    app_module.is_valid_docx_upload(
                        FileStorage(stream=fake_docx, filename=f"unsafe-{index}.docx")
                    )
                )

        symlink_docx = BytesIO()
        symlink_info = zipfile.ZipInfo("word/link.xml")
        symlink_info.create_system = 3
        symlink_info.external_attr = (stat.S_IFLNK | 0o777) << 16
        with zipfile.ZipFile(symlink_docx, "w") as archive:
            archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
            archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
            archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
            archive.writestr(symlink_info, b"<target/>")
        symlink_docx.seek(0)

        self.assertFalse(
            app_module.is_valid_docx_upload(
                FileStorage(stream=symlink_docx, filename="symlink-member.docx")
            )
        )

    def test_docx_validation_rejects_nul_truncated_member_names(self):
        disguised_content_types = b"[Content_Types].xmlX"
        disguised_document = b"word/document.xmlX"
        payload = BytesIO()
        with zipfile.ZipFile(payload, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr(disguised_content_types.decode(), MINIMAL_CONTENT_TYPES_XML)
            archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
            archive.writestr(disguised_document.decode(), MINIMAL_DOCUMENT_XML)

        archive_bytes = payload.getvalue().replace(
            disguised_content_types,
            b"[Content_Types].xml\x00",
        ).replace(
            disguised_document,
            b"word/document.xml\x00",
        )
        with zipfile.ZipFile(BytesIO(archive_bytes)) as archive:
            members = archive.infolist()
            self.assertEqual(
                [member.filename for member in members],
                ["[Content_Types].xml", "_rels/.rels", "word/document.xml"],
            )
            self.assertTrue(any(member.orig_filename != member.filename for member in members))

        stream = BytesIO(archive_bytes)
        self.assertFalse(
            app_module.is_valid_docx_upload(
                FileStorage(stream=stream, filename="nul-truncated.docx")
            )
        )
        self.assertEqual(stream.tell(), 0)

        with tempfile.TemporaryDirectory() as temp_dir:
            output_path = Path(temp_dir) / "nul-truncated-output.docx"
            output_path.write_bytes(archive_bytes)
            self.assertFalse(app_module.is_valid_generated_docx(output_path))

