    def test_docx_validation_rejects_dangerous_compression_ratio(self):
        fake_docx = BytesIO(self.build_high_compression_binary_docx())
        with zipfile.ZipFile(BytesIO(fake_docx.getvalue())) as archive:
            payload_info = archive.getinfo("word/embeddings/payload.bin")
        self.assertGreater(
            payload_info.file_size / payload_info.compress_size,
            app_module.MAX_DOCX_NON_XML_COMPRESSION_RATIO,
        )

