    def test_docx_validation_accepts_legitimate_highly_compressible_table(self):
        document = Document()
        document.add_paragraph("大规模数据表压缩兼容性研究")
        document.add_paragraph("摘要：本文验证合法高压缩率表格文档的兼容性。")
        document.add_paragraph("关键词：数据表 压缩率")
        table = document.add_table(rows=300, cols=5)
        for row_index, row in enumerate(table.rows):
            for column_index, cell in enumerate(row.cells):
                cell.text = str((row_index + column_index) % 10)

        payload = BytesIO()
        document.save(payload)
        archive_bytes = payload.getvalue()
        with zipfile.ZipFile(BytesIO(archive_bytes)) as archive:
            document_info = archive.getinfo("word/document.xml")
        compression_ratio = document_info.file_size / document_info.compress_size
        self.assertGreater(compression_ratio, 50)

        upload_stream = BytesIO(archive_bytes)
        self.assertTrue(
            app_module.is_valid_docx_upload(
                FileStorage(stream=upload_stream, filename="compressible-table.docx")
            )
        )
        self.assertEqual(upload_stream.tell(), 0)

        with tempfile.TemporaryDirectory() as temp_dir:
            temp_path = Path(temp_dir)
            input_path = temp_path / "compressible-table.docx"
            output_path = temp_path / "compressible-table-output.docx"
            input_path.write_bytes(archive_bytes)

            summary = format_paper_module.format_academic_paper(
                input_path,
                output_path,
            )

            self.assertIsInstance(summary, dict)
            self.assertTrue(app_module.is_valid_generated_docx(output_path))
            reopened = Document(output_path)
            self.assertEqual(len(reopened.tables), 1)
            self.assertEqual(reopened.tables[0].cell(299, 4).text, "3")

