    def test_docx_validation_rejects_excessive_total_xml_size(self):
        original_member_limit = app_module.MAX_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES
        original_total_limit = app_module.MAX_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES
        styles_xml = (
            f'<w:styles xmlns:w="{app_module.WORDPROCESSINGML_NAMESPACE}">'
            '<w:style w:type="paragraph" w:styleId="Target"/>'
            "</w:styles>"
        ).encode()
        app_module.MAX_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES = (
            max(
                len(MINIMAL_CONTENT_TYPES_XML),
                len(MINIMAL_ROOT_RELS_XML),
                len(MINIMAL_DOCUMENT_XML),
                len(styles_xml),
            )
            + 32
        )
        app_module.MAX_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES = (
            len(MINIMAL_CONTENT_TYPES_XML)
            + len(MINIMAL_ROOT_RELS_XML)
            + len(MINIMAL_DOCUMENT_XML)
            + 16
        )
        fake_docx = BytesIO()
        try:
            with zipfile.ZipFile(fake_docx, "w", compression=zipfile.ZIP_STORED) as archive:
                archive.writestr("[Content_Types].xml", MINIMAL_CONTENT_TYPES_XML)
                archive.writestr("_rels/.rels", MINIMAL_ROOT_RELS_XML)
                archive.writestr("word/document.xml", MINIMAL_DOCUMENT_XML)
                archive.writestr("word/styles.xml", styles_xml)
            fake_docx.seek(0)

            self.assertFalse(
                app_module.is_valid_docx_upload(FileStorage(stream=fake_docx, filename="too-much-xml.docx"))
            )
            self.assertEqual(fake_docx.tell(), 0)
        finally:
            app_module.MAX_DOCX_XML_MEMBER_UNCOMPRESSED_BYTES = original_member_limit
            app_module.MAX_DOCX_TOTAL_XML_UNCOMPRESSED_BYTES = original_total_limit

