    def test_format_text_async_streams_progress_and_exposes_result(self):
        start_response = self.client.post(
            "/api/format_text_async",
            json={
                "text": (
                    "基于多元回归模型的城市化研究\n"
                    "摘要：这是摘要内容\n"
                    "关键词：城市化 回归\n"
                    "1 引言\n"
                    "1.1 研究背景\n"
                    "正文内容"
                )
            },
        )

        self.assertEqual(start_response.status_code, 202)
        start_data = start_response.get_json()
        self.assertTrue(start_data["success"])

        events_response = self.client.get(start_data["events_url"], buffered=True)
        events_text = events_response.get_data(as_text=True)
        self.assertEqual(events_response.status_code, 200)
        self.assertIn("event: progress", events_text)
        self.assertIn("event: complete", events_text)
        self.assertIn("识别标题层级", events_text)

        result_response = self.client.get(start_data["result_url"])
        result_data = result_response.get_json()
        self.assertEqual(result_response.status_code, 200)
        self.assertTrue(result_data["success"])
        self.assertEqual(result_data["format_summary"]["stats"]["heading_l2"], 1)

    def test_format_text_async_cleans_partial_output_after_unexpected_failure(self):
        original_formatter = app_module.format_academic_paper_from_text

        def broken_formatter(_text, output_path, *_args, **_kwargs):
            Path(output_path).write_bytes(b"partial-output")
            raise RuntimeError(f"formatter crashed after writing {output_path}")

        app_module.format_academic_paper_from_text = broken_formatter
        try:
            with self.assertLogs(app_module.logger, level="ERROR") as logs:
                start_response = self.client.post(
                    "/api/format_text_async",
                    json={
                        "text": (
                            "基于多元回归模型的城市化研究\n"
                            "摘要：这是摘要内容\n"
                            "关键词：城市化 回归\n"
                            "正文内容"
                        )
                    },
                )
                self.assertEqual(start_response.status_code, 202)
                start_data = start_response.get_json()

                events_response = self.client.get(start_data["events_url"], buffered=True)
                events_text = events_response.get_data(as_text=True)
                self.assertEqual(events_response.status_code, 200)
                self.assertIn("event: failed", events_text)

            result_response = self.client.get(start_data["result_url"])
            self.assertEqual(result_response.status_code, 500)
            self.assertEqual(
                result_response.get_json(),
                {
                    "success": False,
                    "error": "服务器内部错误，请稍后重试。",
                    "status": "failed",
                    "terminal": True,
                },
            )
            self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
            log_text = "\n".join(logs.output)
            self.assertIn("异步文本排版出现异常: RuntimeError: formatter crashed after writing", log_text)
            self.assertIn("_output.docx", log_text)
            self.assertNotIn(str(self.output_dir), log_text)
            self.assertNotIn("Traceback", log_text)
        finally:
            app_module.format_academic_paper_from_text = original_formatter

    def test_format_text_async_reports_output_hard_limit(self):
        with patch.multiple(
            app_module,
            MAX_OUTPUT_FILE_BYTES=1024,
            OUTPUT_STORAGE_RESERVATION_BYTES=1024,
            MIN_OUTPUT_FREE_BYTES=0,
        ):
            start_response = self.client.post(
                "/api/format_text_async",
                json={"text": "论文标题\n摘要：测试\n关键词：测试\n正文"},
            )
            self.assertEqual(start_response.status_code, 202)
            start_data = start_response.get_json()

            events_response = self.client.get(start_data["events_url"], buffered=True)
            self.assertIn("event: failed", events_response.get_data(as_text=True))
            result_response = self.client.get(start_data["result_url"])

        self.assertEqual(result_response.status_code, 413)
        self.assertEqual(
            result_response.get_json(),
            {
                "success": False,
                "error": app_module.OUTPUT_TOO_LARGE_MESSAGE,
                "status": "failed",
                "terminal": True,
            },
        )
        self.assertEqual(list(self.output_dir.glob("*_output.docx")), [])
        self.assertEqual(app_module.ACTIVE_OUTPUT_RESERVATIONS, {})

